def load_program_execution_sources(root: Path = ROOT) -> dict[str, str]:
    """Load the existing canonical program inputs for one fresh reconciliation."""
    sources: dict[str, str] = {}
    for owner, relative in PROGRAM_EXECUTION_SOURCE_PATHS.items():
        path = root / relative
        sources[owner] = path.read_text(encoding="utf-8")
    return sources


def _plain_live_value(live: dict[str, str], key: str) -> str:
    return live.get(key, "").strip("`").strip()


SERVICE_FAILURE_AUTOMATION_PROGRAM_ID = "V7_SERVICE_FAILURE_AUTOMATION_EVOLUTION_PROGRAM_V1"
SERVICE_FAILURE_AUTOMATION_M1 = "V7_SERVICE_FAILURE_AUTOMATION_EVOLUTION_M1_DURABLE_INCIDENT_FRONTIER_AND_OMP_CONSUMER_V1"
SERVICE_FAILURE_AUTOMATION_CAUSAL_M2 = "CAUSAL_M2_ATOMIC_TRANSITION_AND_RECEIPT_LINKAGE"
SERVICE_FAILURE_AUTOMATION_CAUSAL_M3 = "CAUSAL_M3_ACTIVE_INCIDENT_REVALIDATION"


def _read_jsonl_records(path: Path) -> list[dict[str, Any]]:
    try:
        lines = path.read_text(encoding="utf-8", errors="replace").splitlines()
    except OSError:
        return []
    records: list[dict[str, Any]] = []
    for line in lines:
        try:
            row = json.loads(line)
        except json.JSONDecodeError:
            continue
        if isinstance(row, dict):
            records.append(row)
    return records


def _append_jsonl_record(path: Path, row: dict[str, Any]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open("a", encoding="utf-8") as handle:
        handle.write(json.dumps(row, ensure_ascii=False, sort_keys=True) + "\n")
        handle.flush()
        os.fsync(handle.fileno())


def _read_json_object(path: Path) -> dict[str, Any]:
    try:
        payload = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return {}
    return payload if isinstance(payload, dict) else {}


def _write_json_object_atomic(path: Path, payload: dict[str, Any]) -> None:
    """Atomically update the existing L3 compact-state owner.

    JSONL closures remain the immutable transaction source. This function only
    materializes their durable receipt into the existing state read model.
    """
    path.parent.mkdir(parents=True, exist_ok=True)
    fd, temporary_name = tempfile.mkstemp(prefix=f".{path.name}.tmp.", dir=str(path.parent))
    temporary = Path(temporary_name)
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as handle:
            json.dump(payload, handle, ensure_ascii=False, sort_keys=True)
            handle.write("\n")
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(temporary, path)
    finally:
        with contextlib.suppress(FileNotFoundError):
            temporary.unlink()


def reconcile_service_failure_omp_receipts_to_incident_state(
    *, state_dir: Path,
) -> dict[str, Any]:
    """Materialize immutable OMP receipts in the existing compact L3 state.

    The receipt is the linearization point under `closure-records.lock`.
    Reconciliation is idempotent and also repairs an interrupted receipt ->
    read-model handoff on the next existing consumer invocation.
    """
    resolved_state_dir = Path(state_dir)
    closure_path = resolved_state_dir / "closure-records.jsonl"
    state_path = resolved_state_dir / "l3-runtime-state.json"
    rows = _read_jsonl_records(closure_path)
    receipts = [
        row for row in rows
        if str(row.get("object_type") or "") == "service_failure_automation_omp_consumption"
        and str(row.get("closure_state") or "") == "OMP_CONSUMED"
    ]
    state = _read_json_object(state_path)
    incidents = state.get("incidents") if isinstance(state.get("incidents"), dict) else {}
    if not receipts:
        return {
            "schema_version": "v7.service-failure-omp-receipt-incident-reconciliation.v1",
            "receipt_count": 0, "projected_receipts": 0, "changed_records": 0,
            "missing_incident_projections": 0, "invalid_open_incidents": 0,
            "final_verdict": "PASS", "read_model_written": False,
        }
    latest_by_obligation: dict[str, dict[str, Any]] = {}
    for receipt in sorted(receipts, key=lambda row: str(row.get("consumed_at") or "")):
        obligation_id = str(receipt.get("automation_obligation_id") or "")
        if obligation_id:
            latest_by_obligation[obligation_id] = receipt
    changed = 0
    projected = 0
    missing = 0
    for obligation_id, receipt in latest_by_obligation.items():
        incident_key = str(receipt.get("incident_key") or "")
        source_incident_id = str(receipt.get("source_incident_id") or "")
        situation_id = str(receipt.get("situation_id") or "")
        decision_trace_id = str(receipt.get("decision_trace_id") or "")
        matches = [
            (key, record)
            for key, record in incidents.items()
            if isinstance(record, dict)
            and str(record.get("authority_object") or "") == "PASSIVE_SERVICE_FAILURE_CAPTURE"
            and (
                (incident_key and str(key) == incident_key)
                or str(record.get("obligation_id") or "") == obligation_id
                or (
                    not incident_key
                    and source_incident_id
                    and situation_id
                    and decision_trace_id
                    and str(record.get("incident_id") or "") == source_incident_id
                    and str(record.get("situation_id") or "") == situation_id
                    and str(record.get("decision_trace_id") or "") == decision_trace_id
                )
            )
        ]
        if not matches:
            # Pre-M1 test/legacy obligations remain valid OMP evidence. A M1
            # obligation explicitly carries its compact key and must never
            # silently lose the producer -> consumer link.
            if incident_key:
                missing += 1
            continue
        for key, record in matches:
            if str(record.get("incident_state") or "") == "INTENT_CLOSED":
                continue
            desired = {
                **record,
                "obligation_id": obligation_id,
                "omp_consumption_state": "OMP_CONSUMED",
                "omp_receipt_id": str(receipt.get("object_id") or ""),
                "omp_receipt_transition_id": "omptr_" + hashlib.sha256(
                    str(receipt.get("object_id") or obligation_id).encode("utf-8")
                ).hexdigest()[:24],
                "next_required_consumer": "tools/v7_sync_lib.continue_omp_engineering_control_loop",
                "reentry_condition": (
                    "existing OMP residual recomputation consumes a new owner-backed "
                    f"state change for {str(receipt.get('next_action') or 'NONE')}"
                ),
                "causal_lineage": {
                    **(record.get("causal_lineage") if isinstance(record.get("causal_lineage"), dict) else {}),
                    "obligation_id": obligation_id,
                    "omp_receipt_id": str(receipt.get("object_id") or ""),
                    "parent_transition_id": str(record.get("transition_id") or ""),
                },
                "causal_invariant": {
                    "name": "OPEN_INCIDENT_REQUIRES_SUCCESSOR_AND_REENTRY",
                    "valid": True,
                },
            }
            comparable_record = {name: value for name, value in record.items() if name != "updated_at"}
            comparable_desired = {name: value for name, value in desired.items() if name != "updated_at"}
            if comparable_record != comparable_desired:
                desired["updated_at"] = utc_now()
                incidents[key] = desired
                changed += 1
            projected += 1
    invalid_open = sum(
        1 for record in incidents.values()
        if isinstance(record, dict)
        and str(record.get("authority_object") or "") == "PASSIVE_SERVICE_FAILURE_CAPTURE"
        and str(record.get("incident_state") or "") != "INTENT_CLOSED"
        and (not str(record.get("next_required_consumer") or "") or not str(record.get("reentry_condition") or ""))
    )
    final_verdict = "PASS" if not missing and not invalid_open else (
        "CAUSAL_LINEAGE_BROKEN" if missing else "INVALID_OPEN_INCIDENT_NO_SUCCESSOR"
    )
    if changed:
        state["schema_version"] = str(state.get("schema_version") or "v7.l3-runtime-state.v1")
        state["updated"] = utc_now()
        state["incidents"] = incidents
        _write_json_object_atomic(state_path, state)
    return {
        "schema_version": "v7.service-failure-omp-receipt-incident-reconciliation.v1",
        "receipt_count": len(latest_by_obligation),
        "projected_receipts": projected,
        "changed_records": changed,
        "missing_incident_projections": missing,
        "invalid_open_incidents": invalid_open,
        "final_verdict": final_verdict,
        "read_model_written": bool(changed),
    }


def service_failure_automation_state_dir(*, root: Path = ROOT, state_dir: Optional[Path] = None) -> Path:
    if state_dir is not None:
        return Path(state_dir)
    configured = os.environ.get("V7_SERVICE_FAILURE_STATE_DIR", "").strip()
    if configured:
        return Path(configured)
    return root / "egress" / "state"


def service_failure_active_incident_scope_projection(
    source_incident_id: str, *, state_dir: Path,
) -> dict[str, Any]:
    """Read the existing L3 compact scope projection for one incident.

    This is a projection bridge only.  The lifecycle owner remains
    ``l3-runtime-state.json``; CPS receives no user list and no inferred
    historical route.  A malformed or unbalanced projection is ignored so it
    cannot turn a live incident into a false executable frontier.
    """
    if not source_incident_id:
        return {}
    state_path = state_dir / "l3-runtime-state.json"
    try:
        state = json.loads(state_path.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return {}
    incidents = state.get("incidents") if isinstance(state.get("incidents"), dict) else {}
    for record in incidents.values():
        if not isinstance(record, dict):
            continue
        if str(record.get("source_incident_id") or record.get("incident_id") or "") != source_incident_id:
            continue
        # The L3 owner now carries two intentionally non-interchangeable
        # projections.  CPS consumes only the current-source denominator;
        # cumulative packet lineage is forwarded as context and can never
        # reduce the current failed-source scope by itself.
        scope = (
            record.get("current_source_scope")
            if isinstance(record.get("current_source_scope"), dict)
            else (record.get("scope_accounting") if isinstance(record.get("scope_accounting"), dict) else {})
        )
        affected = int(scope.get("affected_scope_count") or 0)
        protected = int(scope.get("protected_scope_count") or 0)
        unresolved = int(scope.get("unresolved_scope_count") or 0)
        excluded = int(scope.get("explicitly_excluded_or_recovered_scope_count") or 0)
        if (
            str(scope.get("status") or "") != "ACCOUNTED"
            or affected != protected + unresolved + excluded
            or not str(scope.get("affected_scope_fingerprint") or "")
            or bool(scope.get("raw_user_list_stored"))
        ):
            return {}
        cumulative = record.get("incident_cumulative_scope") if isinstance(record.get("incident_cumulative_scope"), dict) else {}
        return {
            **scope,
            "current_source_scope": scope,
            "incident_cumulative_scope": cumulative,
            "incident_id": source_incident_id,
            "incident_generation": str(record.get("incident_generation") or ""),
            "incident_state": str(record.get("incident_state") or ""),
            "channel_incident_state": str(record.get("channel_incident_state") or ""),
            "next_required_consumer": str(record.get("next_required_consumer") or ""),
            "reentry_condition": str(record.get("reentry_condition") or ""),
            "last_execution_feedback_id": str(record.get("last_execution_feedback_id") or ""),
            "outcome_id": str(record.get("outcome_id") or ""),
            "learning_id": str(record.get("learning_id") or ""),
            "owner": "l3-runtime-state.json via tools/v7-users-autoswitch",
        }
    return {}


def service_failure_automation_frontier(
    *, root: Path = ROOT, state_dir: Optional[Path] = None,
) -> dict[str, Any]:
    """Read the existing closure owner for one unconsumed automation obligation."""
    resolved_state_dir = service_failure_automation_state_dir(root=root, state_dir=state_dir)
    closure_path = resolved_state_dir / "closure-records.jsonl"
    rows = _read_jsonl_records(closure_path)
    consumed = {
        str(row.get("automation_obligation_id") or "")
        for row in rows
        if str(row.get("object_type") or "") == "service_failure_automation_omp_consumption"
        and str(row.get("closure_state") or "") == "OMP_CONSUMED"
    }
    pending = [
        row for row in rows
        if str(row.get("object_type") or "") == "service_failure_automation_obligation"
        and str(row.get("closure_state") or "") == "READY_FOR_OMP_CONSUMPTION"
        and str(row.get("automation_obligation_id") or "") not in consumed
    ]
    pending.sort(key=lambda row: str(row.get("created_at") or row.get("observed_at") or ""), reverse=True)
    selected = pending[0] if pending else {}
    return {
        "schema_version": "v7.service-failure-automation-frontier.v1",
        "owner": "existing closure-records + OMP continuation owners",
        "state_dir": str(resolved_state_dir),
        "closure_path": str(closure_path),
        "pending_count": len(pending),
        "selected": selected,
        "final_verdict": "READY" if selected else "NO_PENDING_OBLIGATION",
        "new_registry_created": False,
    }


def consume_service_failure_automation_frontier(
    *, root: Path = ROOT, state_dir: Optional[Path] = None, persist_cps: bool = False,
    obligation_override: Optional[dict[str, Any]] = None, record_receipt: bool = True,
    _lock_held: bool = False,
) -> dict[str, Any]:
    """Consume one existing service-failure obligation through the OMP owner.

    The durable source and the consumption receipt both live in the existing
    closure owner.  No Candidate, Packet, lease, Runtime action or Authority
    change can be produced here.
    """
    resolved_state_dir = service_failure_automation_state_dir(root=root, state_dir=state_dir)
    if record_receipt and not _lock_held:
        # The sidecar is only the existing closure owner's interprocess
        # coordination primitive.  Hold it across select -> CPS projection ->
        # receipt append so two Continue OMP processes cannot consume the same
        # durable obligation or publish two successors.
        lock_path = resolved_state_dir / "closure-records.lock"
        lock_path.parent.mkdir(parents=True, exist_ok=True)
        with lock_path.open("a+", encoding="utf-8") as lock_handle:
            fcntl.flock(lock_handle.fileno(), fcntl.LOCK_EX)
            try:
                return consume_service_failure_automation_frontier(
                    root=root,
                    state_dir=resolved_state_dir,
                    persist_cps=persist_cps,
                    obligation_override=obligation_override,
                    record_receipt=record_receipt,
                    _lock_held=True,
                )
            finally:
                fcntl.flock(lock_handle.fileno(), fcntl.LOCK_UN)

    pre_receipt_reconciliation = reconcile_service_failure_omp_receipts_to_incident_state(
        state_dir=resolved_state_dir,
    )
    if pre_receipt_reconciliation.get("final_verdict") != "PASS":
        return {
            "schema_version": "v7.service-failure-automation-omp-consumption.v1",
            "final_verdict": "STOP_SAFE",
            "errors": ["existing_omp_receipt_compact_projection_invalid"],
            "incident_projection_reconciliation": pre_receipt_reconciliation,
        }
    frontier = service_failure_automation_frontier(root=root, state_dir=resolved_state_dir)
    obligation = obligation_override if isinstance(obligation_override, dict) else (
        frontier.get("selected") if isinstance(frontier.get("selected"), dict) else {}
    )
    if not obligation:
        return {
            "schema_version": "v7.service-failure-automation-omp-consumption.v1",
            "final_verdict": "NO_PENDING_OBLIGATION",
            "frontier": frontier,
            "incident_projection_reconciliation": pre_receipt_reconciliation,
            "runtime_impact": "NONE", "production_impact": "NONE", "routing_impact": "NONE",
            "user_movement": 0, "authority_impact": "NONE", "production_maturity_impact": "NO_CHANGE",
        }
    obligation_id = str(obligation.get("automation_obligation_id") or "")
    classification = str(obligation.get("stop_safe_classification") or "STOP_SAFE_DATA_OR_EVIDENCE_GAP")
    product_frontier = str(obligation.get("product_evolution_frontier") or "NONE")
    incident_frontier = str(obligation.get("incident_frontier") or "V7_SERVICE_FAILURE_AUTOMATION_INCIDENT_RECONCILIATION")
    source_incident_id = str(obligation.get("source_incident_id") or "")
    scope_projection = obligation.get("incident_scope_accounting")
    scope_projection = scope_projection if isinstance(scope_projection, dict) else {}
    if not scope_projection:
        scope_projection = service_failure_active_incident_scope_projection(
            source_incident_id, state_dir=resolved_state_dir,
        )
    active_incident_drain = (
        str(scope_projection.get("status") or "") == "ACCOUNTED"
        and int(scope_projection.get("unresolved_scope_count") or 0) > 0
        and str(scope_projection.get("channel_incident_state") or "OPEN") != "RECOVERED"
    )
    # A continuing degraded source with an accountable unresolved cohort is an
    # internal safe successor, never a REAL_WORLD_LIMIT.  The pre-existing
    # fresh-event product frontier remains the revalidation input, while this
    # canonical incident frontier prevents CPS from reporting NO_WORK.
    next_action = (
        "CONTINUE_ACTIVE_INCIDENT_REVALIDATION_AND_DRAIN"
        if active_incident_drain else
        (product_frontier if product_frontier != "NONE" else incident_frontier)
    )
    legal_terminal = classification == "CORRECT_SAFE_TERMINAL" and not active_incident_drain
    authority_boundary = classification in {
        "STOP_SAFE_AUTHORITY_REQUIRED",
        "STOP_SAFE_EXTERNAL_OWNER_REQUIRED",
    }
    receipt = {
        "schema_version": "v7.service-failure-automation-omp-consumption.v1",
        "object_type": "service_failure_automation_omp_consumption",
        "object_id": "sfomp_" + hashlib.sha256(obligation_id.encode("utf-8")).hexdigest()[:24],
        "automation_obligation_id": obligation_id,
        "closure_state": "OMP_CONSUMED",
        "consumed_at": utc_now(),
        "program_id": SERVICE_FAILURE_AUTOMATION_PROGRAM_ID,
        "mission_id": SERVICE_FAILURE_AUTOMATION_CAUSAL_M2,
        "source_incident_id": source_incident_id,
        "incident_key": str(obligation.get("incident_key") or ""),
        "situation_id": str(obligation.get("situation_id") or ""),
        "decision_trace_id": str(obligation.get("decision_trace_id") or ""),
        "classification": classification,
        "incident_frontier": incident_frontier,
        "product_evolution_frontier": product_frontier,
        "next_action": next_action,
        "incident_scope_accounting": scope_projection,
        "current_source_scope": (
            dict(scope_projection.get("current_source_scope") or {})
            if isinstance(scope_projection.get("current_source_scope"), dict) else dict(scope_projection)
        ),
        "incident_cumulative_scope": (
            dict(scope_projection.get("incident_cumulative_scope") or {})
            if isinstance(scope_projection.get("incident_cumulative_scope"), dict) else {}
        ),
        "source_incident_frontier": incident_frontier,
        "source_product_evolution_frontier": product_frontier,
        "legal_terminal": legal_terminal,
        "real_caller": "tools/v7-service-matrix-refresh-all",
        "real_consumer": "continue_omp_engineering_control_loop",
        "runtime_mutation_performed": False,
        "routing_mutation_performed": False,
        "users_moved": 0,
        "apply_executed": False,
        "authority_expanded": False,
        "production_maturity_changed": False,
    }
    receipt_reconciliation: dict[str, Any] = pre_receipt_reconciliation
    if record_receipt:
        # The durable receipt is the linearization point.  The compact L3
        # projection is materialized while the same existing owner lock is
        # held; an interrupted post-receipt write is repaired by the preflight
        # reconciliation above, never by issuing a second receipt.
        _append_jsonl_record(Path(frontier["closure_path"]), receipt)
        receipt_reconciliation = reconcile_service_failure_omp_receipts_to_incident_state(
            state_dir=resolved_state_dir,
        )
        if receipt_reconciliation.get("final_verdict") != "PASS":
            return {
                "schema_version": "v7.service-failure-automation-omp-consumption.v1",
                "final_verdict": "STOP_SAFE",
                "frontier": frontier,
                "receipt": receipt,
                "incident_projection_reconciliation": receipt_reconciliation,
                "errors": ["omp_receipt_written_compact_projection_requires_existing_owner_repair"],
            }
    atomic: dict[str, Any] = {"ok": True, "status": "CPS_PERSIST_NOT_REQUESTED"}
    if persist_cps:
        cps_path = root / "docs/programs/V7_CURRENT_PROGRAM_STATE.md"
        cps_text = cps_path.read_text(encoding="utf-8")
        state = _normalized_state_from_live_cps(cps_text)
        fingerprint = hashlib.sha256(json.dumps(receipt, sort_keys=True, separators=(",", ":")).encode("utf-8")).hexdigest()
        if active_incident_drain:
            stop_condition = "NONE"
            continuation_decision = "CONTINUE_ACTIVE_INCIDENT_REVALIDATION_AND_DRAIN"
            terminal_class = "NONE"
            terminal_state = "NONE_ACTIVE_INCIDENT_DRAIN_SUCCESSOR_READY"
            external_input = "NONE"
            authority_required = "NO_INSIDE_ACTIVE_STANDING_POLICY_AND_LIVE_GATES"
            safe_next_action = (
                "CONTINUE THE SAME OPEN VLESS INCIDENT THROUGH THE EXISTING FRESH MATRIX "
                "REVALIDATION -> PLANNER -> NEW CANDIDATE/PACKET/LEASE PATH; DO NOT REUSE HISTORICAL OBJECTS"
            )
        elif authority_boundary:
            stop_condition = "ENGINEERING_AUTHORITY"
            continuation_decision = "PROGRAM_TERMINAL_ENGINEERING_AUTHORITY"
            terminal_class = "ENGINEERING_AUTHORITY"
            terminal_state = "ENGINEERING_AUTHORITY_SERVICE_FAILURE_ACTION_CLASS_RECONCILIATION_REQUIRED"
            external_input = "EXACT_ACTION_CLASS_AUTHORITY_RECONCILIATION"
            authority_required = "YES_FOR_CERTIFICATION_POOL_OR_DELIBERATE_CONTROLLED_CONDITION"
            safe_next_action = "PRESERVE THE INCIDENT AND REQUEST ONLY THE EXACT OWNER-ISSUED ONE-USE ACTION-CLASS CONTRACT; DO NOT APPLY OR MOVE USERS"
        elif legal_terminal:
            stop_condition = "REAL_WORLD_LIMIT"
            continuation_decision = "PROGRAM_TERMINAL_REAL_WORLD_LIMIT"
            terminal_class = "REAL_WORLD_LIMIT"
            terminal_state = "REAL_WORLD_LIMIT_SERVICE_FAILURE_TERMINAL_REENTRY_REQUIRED"
            external_input = "NEXT_MATERIAL_SERVICE_FAILURE_OR_PRODUCT_EVOLUTION_OBLIGATION"
            authority_required = "NO_INSIDE_APPROVED_POLICY"
            safe_next_action = "KEEP INCIDENT CAPTURE READY AND CONTINUE INDEPENDENT PRODUCT EVOLUTION FRONTIER"
        else:
            # A proven code/caller/data gap stays inside engineering only when
            # its existing BDP/OMP route is represented by the next revision.
            stop_condition = "NONE"
            continuation_decision = "CONTINUE_PROGRAM_FRONTIER"
            terminal_class = "NONE"
            terminal_state = "NONE_SERVICE_FAILURE_AUTOMATION_REPAIR_FRONTIER_READY"
            external_input = "NONE"
            authority_required = "NO_INSIDE_EXISTING_ENGINEERING_PROGRAM_SCOPE"
            safe_next_action = "RECONCILE THE EXACT STOP_SAFE CLASSIFICATION THROUGH EXISTING BDP/OMP OWNERS"
        state.update({
            "active_program": SERVICE_FAILURE_AUTOMATION_PROGRAM_ID,
            "current_stop_condition": stop_condition,
            "current_active_scope": (
                "SERVICE_FAILURE_AUTOMATION_ACTIVE_INCIDENT_DRAIN"
                if active_incident_drain else "SERVICE_FAILURE_AUTOMATION_INCIDENT_AND_PRODUCT_EVOLUTION_FRONTIERS_ACTIVE"
            ),
            "current_scope_class": "SERVICE_FAILURE_AUTOMATION_EVOLUTION",
            "current_state_generation": f"cpsgen_SFA_{fingerprint[:12].upper()}",
            "current_transition_id": "SERVICE_FAILURE_AUTOMATION_M1_OMP_CONSUMED_V1",
            "current_next_action_id": next_action if not legal_terminal else "WAIT_FOR_NEXT_MATERIAL_SERVICE_FAILURE_OR_PRODUCT_EVOLUTION_OBLIGATION",
            "current_safe_next_action": safe_next_action,
            "current_program_execution_frontier": next_action if not (legal_terminal or authority_boundary) else "NONE",
            "current_execution_frontier": next_action if not (legal_terminal or authority_boundary) else "NONE",
            "program_frontier_input": f"service failure automation obligation {obligation_id}",
            "program_frontier_expected_output": "STOP_SAFE CLASSIFICATION -> EXISTING BDP/OMP ROUTE OR LEGAL TERMINAL",
            "smallest_existing_next_action": next_action,
            "last_responsible_link": str(obligation.get("last_responsible_link") or "service failure obligation -> OMP consumer"),
            "continuation_decision": continuation_decision,
            "program_terminal_class": terminal_class,
            "program_terminal_state": terminal_state,
            "authority_required_now": authority_required,
            "wip_authority_required_now": authority_required,
            "wip_current_primary_stop": stop_condition,
            "wip_smallest_existing_next_action_id": next_action,
            "wip_smallest_existing_next_action": next_action,
            "omp_continuation_required": "TRUE" if not (legal_terminal or authority_boundary) else "FALSE",
            "external_input_required": "FALSE" if not (legal_terminal or authority_boundary) else "TRUE",
            "external_input_type": external_input,
            "next_mission_formed": "TRUE" if not (legal_terminal or authority_boundary) else "FALSE",
            "next_mission_id": SERVICE_FAILURE_AUTOMATION_CAUSAL_M3 if active_incident_drain else (SERVICE_FAILURE_AUTOMATION_M1 if not (legal_terminal or authority_boundary) else "NONE"),
            "state_captured": utc_now(),
        })
        scope_overrides = {}
        if active_incident_drain:
            scope_overrides = {
                "CURRENT_VLESS_INCIDENT_ID": f"`{source_incident_id}`",
                "CURRENT_VLESS_INCIDENT_GENERATION": f"`{scope_projection.get('incident_generation') or ''}`",
                "CURRENT_VLESS_AFFECTED_SCOPE": f"`{int(scope_projection.get('affected_scope_count') or 0)}`",
                "CURRENT_VLESS_PROTECTED_SCOPE": f"`{int(scope_projection.get('protected_scope_count') or 0)}`",
                "CURRENT_VLESS_UNRESOLVED_SCOPE": f"`{int(scope_projection.get('unresolved_scope_count') or 0)}`",
                "CURRENT_VLESS_EXCLUDED_OR_RECOVERED_SCOPE": f"`{int(scope_projection.get('explicitly_excluded_or_recovered_scope_count') or 0)}`",
                "CURRENT_VLESS_SCOPE_FINGERPRINT": f"`{scope_projection.get('affected_scope_fingerprint') or ''}`",
                "CURRENT_VLESS_SCOPE_ACCOUNTING": "`ACCOUNTED; current route truth + exact source-scope lineage; raw user list not stored`",
                "INCIDENT_FRONTIER": "`CONTINUE_ACTIVE_INCIDENT_REVALIDATION_AND_DRAIN`",
                "PRODUCT_EVOLUTION_FRONTIER": f"`{product_frontier}`",
                "CURRENT_SERVICE_FAILURE_DETERMINISTIC_SEQUENCE": "`verified outcome -> scope reconciliation -> CPS/OMP successor -> fresh Matrix revalidation`",
                # The deployed Matrix is the production owner of the next
                # observation/revalidation.  Source CPS records that
                # existing consumer explicitly; it is not a new scheduler.
                "CURRENT_SERVICE_FAILURE_NEXT_REQUIRED_CONSUMER": "`tools/v7-service-matrix-refresh-all`",
                "CURRENT_SERVICE_FAILURE_REENTRY_CONDITION": "`enabled v7-service-matrix-refresh.timer performs fresh observation and consumes the durable active-incident successor`",
                "CURRENT_SERVICE_FAILURE_LAST_OUTCOME_POINTER": f"`{scope_projection.get('outcome_id') or ''}`",
                "CURRENT_SERVICE_FAILURE_LEARNING_POINTER": f"`{scope_projection.get('learning_id') or ''}`",
            }
        atomic = atomic_reconcile_cps(
            cps_path,
            state=state,
            # Safe successors must re-enter through the already certified
            # event-driven OMP owner.  Exact Authority/real-world terminals
            # intentionally suppress a wake and remain external boundaries.
            request_external_wake=not (legal_terminal or authority_boundary),
            expected_generation=_plain_live_value(_markdown_field_table(_markdown_section(cps_text, "## 0. Authoritative Live Current State", "## Authoritative Unfinished Capability Closure Registry")), "CURRENT_STATE_GENERATION"),
            section0_field_overrides=scope_overrides,
        )
        if not atomic.get("ok"):
            return {
                "schema_version": "v7.service-failure-automation-omp-consumption.v1",
                "final_verdict": "STOP_SAFE",
                "frontier": frontier,
                "receipt": receipt,
                "atomic_update": atomic,
                "errors": atomic.get("errors") or ["cps_update_failed"],
            }
    return {
        "schema_version": "v7.service-failure-automation-omp-consumption.v1",
        "final_verdict": "PASS",
        "frontier": frontier,
        "receipt": receipt,
        "incident_projection_reconciliation": receipt_reconciliation,
        "atomic_update": atomic,
        "real_caller": receipt["real_caller"],
        "real_consumer": receipt["real_consumer"],
        "behavior_change": True,
        "next_output": next_action,
        "runtime_impact": "NONE", "production_impact": "NONE", "routing_impact": "NONE",
        "user_movement": 0, "authority_impact": "NONE", "production_maturity_impact": "NO_CHANGE",
        "errors": [],
    }


def reconcile_service_failure_automation_receipt_to_cps(
    receipt: dict[str, Any], *, root: Path = ROOT,
) -> dict[str, Any]:
    """Project a verified production receipt into the canonical source CPS.

    Production hosts intentionally carry runtime evidence, not a duplicate
    documentation corpus.  The source CPS may therefore reconcile a receipt
    only after its immutable identity and forbidden-effect fields validate.
    It never manufactures a second production receipt.
    """
    required = (
        "automation_obligation_id", "source_incident_id", "situation_id",
        "decision_trace_id", "classification", "next_action",
    )
    missing = [key for key in required if not str(receipt.get(key) or "")]
    forbidden = [
        key for key in (
            "runtime_mutation_performed", "routing_mutation_performed",
            "apply_executed", "authority_expanded", "production_maturity_changed",
        ) if receipt.get(key) is not False
    ]
    if (
        str(receipt.get("object_type") or "") != "service_failure_automation_omp_consumption"
        or str(receipt.get("closure_state") or "") != "OMP_CONSUMED"
        or missing or forbidden or int(receipt.get("users_moved") or 0) != 0
    ):
        return {
            "schema_version": "v7.service-failure-automation-source-cps-reconciliation.v1",
            "final_verdict": "STOP_SAFE", "errors": (
                (["receipt_identity_or_effects_invalid"] if not missing and not forbidden else [])
                + [f"missing:{key}" for key in missing]
                + [f"forbidden_effect:{key}" for key in forbidden]
            ),
        }
    # A correctly consumed historical expiry/recovery terminal must not
    # overwrite a newer, independently audit-verified standing-policy
    # frontier.  Both facts are durable and useful: the receipt is consumed
    # through CPS as history, while the newer policy remains the legal owner
    # of the next fresh-event revalidation.  This avoids a producer ->
    # consumer race where an older receipt silently resurrects a stale
    # Authority boundary.
    cps_path = root / "docs/programs/V7_CURRENT_PROGRAM_STATE.md"
    try:
        cps_text = cps_path.read_text(encoding="utf-8")
    except OSError as exc:
        return {
            "schema_version": "v7.service-failure-automation-source-cps-reconciliation.v1",
            "final_verdict": "STOP_SAFE", "errors": [f"cps_unreadable:{exc}"],
        }
    live = _markdown_field_table(_markdown_section(
        cps_text, "## 0. Authoritative Live Current State", "## Authoritative Unfinished Capability Closure Registry",
    ))
    receipt_id = str(receipt.get("object_id") or "")
    active_standing_policy = (
        _plain_live_value(live, "ACTIVE_PROGRAM") == SERVICE_FAILURE_AUTOMATION_PROGRAM_ID
        and _plain_live_value(live, "CURRENT_AUTHORITY_REQUEST_STATUS") == "ACTIVE_OWNER_BACKED_STANDING_POLICY"
        and _plain_live_value(live, "CURRENT_NEXT_ACTION_ID") == "V7_SERVICE_FAILURE_AUTOMATION_FRESH_EVENT_REVALIDATION"
    )
    historical_safe_terminal = str(receipt.get("classification") or "") == "CORRECT_SAFE_TERMINAL"
    if active_standing_policy and historical_safe_terminal:
        receipt_fingerprint = hashlib.sha256(json.dumps({
            "receipt_id": receipt_id,
            "source_incident_id": receipt["source_incident_id"],
            "decision_trace_id": receipt["decision_trace_id"],
            "classification": receipt["classification"],
        }, sort_keys=True, separators=(",", ":")).encode("utf-8")).hexdigest()
        already_projected = _plain_live_value(live, "LAST_SERVICE_FAILURE_RECEIPT_ID") == receipt_id
        if already_projected:
            return {
                "schema_version": "v7.service-failure-automation-source-cps-reconciliation.v1",
                "final_verdict": "PASS", "status": "RECEIPT_ALREADY_CONSUMED_ACTIVE_POLICY_PRESERVED",
                "production_receipt_id": receipt_id, "receipt": receipt,
                "behavior_change": False,
                "next_output": "V7_SERVICE_FAILURE_AUTOMATION_FRESH_EVENT_REVALIDATION",
                "forbidden_effects": {"runtime_apply": False, "routing_mutation": False, "user_movement": False, "authority_expansion": False},
                "errors": [],
            }
        state = _normalized_state_from_live_cps(cps_text)
        state.update({
            "state_captured": utc_now(),
            "current_state_generation": f"cpsgen_SFA_RECEIPT_{receipt_fingerprint[:12].upper()}",
            "current_transition_id": "SERVICE_FAILURE_AUTOMATION_HISTORICAL_RECEIPT_CONSUMED_NO_TERMINAL_OVERRIDE_V1",
            # This branch is reachable only when CPS already names the
            # fresh-event wait, rather than an active Matrix drain.  Preserve
            # the standing policy but normalize all coupled execution fields
            # so a historical receipt cannot leave a ghost formed Mission.
            "current_stop_condition": "REAL_WORLD_LIMIT",
            "current_program_execution_frontier": "NONE",
            "current_execution_frontier": "NONE",
            "authority_required_now": "NO_INSIDE_APPROVED_POLICY",
            "wip_authority_required_now": "NO_INSIDE_APPROVED_POLICY",
            "continuation_decision": "PROGRAM_TERMINAL_REAL_WORLD_LIMIT",
            "program_terminal_class": "REAL_WORLD_LIMIT",
            "program_terminal_state": "REAL_WORLD_LIMIT_WAIT_FOR_FRESH_MATCHING_SERVICE_FAILURE_EVENT",
            "omp_continuation_required": "FALSE",
            "external_input_required": "TRUE",
            "external_input_type": "FRESH_MATCHING_SERVICE_FAILURE_EVENT",
            "next_mission_formed": "FALSE",
            "next_mission_id": "NONE",
            "wip_current_primary_stop": "REAL_WORLD_LIMIT",
            "wip_smallest_existing_next_action_id": "V7_SERVICE_FAILURE_AUTOMATION_FRESH_EVENT_REVALIDATION",
            "wip_smallest_existing_next_action": "V7_SERVICE_FAILURE_AUTOMATION_FRESH_EVENT_REVALIDATION",
            "smallest_existing_next_action": "V7_SERVICE_FAILURE_AUTOMATION_FRESH_EVENT_REVALIDATION",
            "source_summary": (
                "The existing Service Matrix lifecycle and existing OMP consumer preserve historical "
                "safe terminals while the independently audit-verified standing delegated policy remains "
                "active; only a fresh matching owner-backed service-failure event may reenter planner "
                "revalidation with new Candidate/Packet/lease identities."
            ),
        })
        atomic = atomic_reconcile_cps(
            cps_path,
            state=state,
            request_external_wake=False,
            expected_generation=_plain_live_value(live, "CURRENT_STATE_GENERATION"),
            section0_field_overrides={
                "LAST_SERVICE_FAILURE_RECEIPT_ID": f"`{receipt_id}`",
                "LAST_SERVICE_FAILURE_RECEIPT_FINGERPRINT": f"`{receipt_fingerprint}`",
                "LAST_SERVICE_FAILURE_RECEIPT_CLASSIFICATION": "`CORRECT_SAFE_TERMINAL`",
                "LAST_SERVICE_FAILURE_RECEIPT_SOURCE_INCIDENT": f"`{receipt['source_incident_id']}`",
                "LAST_SERVICE_FAILURE_RECEIPT_DECISION_TRACE": f"`{receipt['decision_trace_id']}`",
                "LAST_SERVICE_FAILURE_RECEIPT_CONSUMPTION": "`HISTORICAL_CONSUMED_ACTIVE_STANDING_POLICY_FRONTIER_PRESERVED`",
            },
        )
        return {
            "schema_version": "v7.service-failure-automation-source-cps-reconciliation.v1",
            "final_verdict": "PASS" if atomic.get("ok") else "STOP_SAFE",
            "status": "HISTORICAL_RECEIPT_CONSUMED_ACTIVE_STANDING_POLICY_PRESERVED",
            "atomic_update": atomic,
            "production_receipt_id": receipt_id,
            "receipt": receipt,
            "behavior_change": bool(atomic.get("ok")),
            "next_output": "V7_SERVICE_FAILURE_AUTOMATION_FRESH_EVENT_REVALIDATION",
            "forbidden_effects": {"runtime_apply": False, "routing_mutation": False, "user_movement": False, "authority_expansion": False},
            "errors": [] if atomic.get("ok") else atomic.get("errors") or ["cps_receipt_projection_failed"],
        }
    obligation = {
        "automation_obligation_id": receipt["automation_obligation_id"],
        "source_incident_id": receipt["source_incident_id"],
        "situation_id": receipt["situation_id"],
        "decision_trace_id": receipt["decision_trace_id"],
        "stop_safe_classification": receipt["classification"],
        "incident_frontier": receipt.get("source_incident_frontier") or receipt.get("incident_frontier") or receipt["next_action"],
        "product_evolution_frontier": receipt.get("source_product_evolution_frontier") or receipt.get("product_evolution_frontier") or "NONE",
        "incident_scope_accounting": (
            dict(receipt.get("incident_scope_accounting") or {})
            if isinstance(receipt.get("incident_scope_accounting"), dict) else {}
        ),
        "last_responsible_link": "production OMP receipt -> canonical source CPS reconciliation",
    }
    result = consume_service_failure_automation_frontier(
        root=root,
        state_dir=Path("/nonexistent-service-failure-source-reconciliation"),
        persist_cps=True,
        obligation_override=obligation,
        record_receipt=False,
    )
    result["schema_version"] = "v7.service-failure-automation-source-cps-reconciliation.v1"
    result["production_receipt_id"] = str(receipt.get("object_id") or "")
    result["receipt"] = receipt
    return result


def reconcile_action_class_contract_request_to_cps(
    reconciliation: dict[str, Any], *, root: Path = ROOT,
) -> dict[str, Any]:
    """Atomically project one fresh, read-only M5a Authority request to CPS.

    The request remains non-durable at the Authority owner and this function
    never approves, declines, writes policy, creates a Candidate/Packet/lease,
    or changes Runtime.  CPS only gains an auditable pointer to the exact
    short-lived decision that production already produced through the existing
    autoswitch -> Authority-owner handoff.
    """
    from admin_core import operator_execution

    reconciliation = reconciliation if isinstance(reconciliation, dict) else {}
    request = reconciliation.get("authority_decision_request")
    package = reconciliation.get("approval_package")
    effects = {
        "authority_granted": reconciliation.get("authority_granted"),
        "contract_written": reconciliation.get("contract_written"),
        "runtime_apply": reconciliation.get("runtime_apply"),
        "routing_mutation": reconciliation.get("routing_mutation"),
        "candidate_created": reconciliation.get("candidate_created"),
        "packet_created": reconciliation.get("packet_created"),
        "lease_created": reconciliation.get("lease_created"),
    }
    errors: list[str] = []
    if reconciliation.get("schema_version") != "v7.action-class-contract-reconciliation-request.v1":
        errors.append("action_class_reconciliation_schema_invalid")
    if reconciliation.get("status") != "ACTION_CLASS_CONTRACT_ISSUE_REVIEW_READY":
        errors.append("action_class_request_not_fresh_issue_ready")
    if reconciliation.get("authority_classification") != "ENGINEERING_AUTHORITY_ACTION_CLASS_CONTRACT_REQUEST_READY":
        errors.append("action_class_authority_classification_invalid")
    if reconciliation.get("exact_legal_next_action") != "INDEPENDENT_DECISION_ON_FRESH_ONE_USE_ACTION_CLASS_CONTRACT_REQUEST":
        errors.append("action_class_exact_legal_next_action_invalid")
    if not isinstance(request, dict) or not isinstance(package, dict):
        errors.append("action_class_request_or_package_missing")
        request = {}
        package = {}
    validation = operator_execution.validate_current_action_class_contract_authority_request(
        request, decision="DECLINE", allow_decline=True,
    )
    if not validation.get("ok"):
        errors.extend(str(item) for item in validation.get("errors") or [])
    if package.get("schema_version") != "v7.authority-normalized-approval-package.v1":
        errors.append("action_class_approval_package_schema_invalid")
    if package.get("status") != "AWAITING_INDEPENDENT_AUTHORITY_DECISION" or package.get("actionable") is not True:
        errors.append("action_class_approval_package_not_actionable")
    if package.get("authority_classification") != reconciliation.get("authority_classification"):
        errors.append("action_class_package_classification_mismatch")
    if package.get("request_id") != request.get("request_id") or package.get("request_hash") != request.get("request_hash"):
        errors.append("action_class_package_request_identity_mismatch")
    if package.get("expires_at") != request.get("expires_at"):
        errors.append("action_class_package_expiry_mismatch")
    packet_identity = package.get("packet_identity") if isinstance(package.get("packet_identity"), dict) else {}
    if packet_identity.get("present") is not False or packet_identity.get("packet_id") or packet_identity.get("packet_hash"):
        errors.append("action_class_m5a_packet_must_be_absent")
    if any(value is not False for value in effects.values()) or int(reconciliation.get("users_moved") or 0) != 0:
        errors.append("action_class_reconciliation_forbidden_effect_present")
    expected_forbidden = {
        "contract_issuance", "policy_write", "restore_barrier_write",
        "candidate_creation", "execution_packet_or_lease_creation", "runtime_apply",
        "routing_mutation", "user_movement", "rollback_apply", "authority_expansion",
        "production_maturity_change",
    }
    if not expected_forbidden.issubset({str(item) for item in package.get("forbidden_effects") or []}):
        errors.append("action_class_package_forbidden_effects_incomplete")
    if errors:
        return {
            "schema_version": "v7.action-class-contract-request-source-cps-reconciliation.v1",
            "final_verdict": "STOP_SAFE",
            "status": "ACTION_CLASS_CONTRACT_REQUEST_CPS_RECONCILIATION_REJECTED",
            "errors": sorted(set(errors)),
            "runtime_impact": "NONE", "routing_impact": "NONE", "user_movement": 0,
            "authority_impact": "NONE", "production_maturity_impact": "NO_CHANGE",
        }

    cps_path = root / "docs/programs/V7_CURRENT_PROGRAM_STATE.md"
    try:
        cps_text = cps_path.read_text(encoding="utf-8")
    except OSError as exc:
        return {
            "schema_version": "v7.action-class-contract-request-source-cps-reconciliation.v1",
            "final_verdict": "STOP_SAFE", "status": "CPS_UNREADABLE_STOP_SAFE",
            "errors": [str(exc)],
        }
    live = _markdown_field_table(_markdown_section(
        cps_text, "## 0. Authoritative Live Current State",
        "## Authoritative Unfinished Capability Closure Registry",
    ))
    expected_generation = _plain_live_value(live, "CURRENT_STATE_GENERATION")
    request_fingerprint = hashlib.sha256(json.dumps({
        "request_id": request["request_id"], "request_hash": request["request_hash"],
        "expires_at": request["expires_at"], "incident_generation": request["incident_generation"],
        "source_generation": request["source_generation"],
    }, sort_keys=True, separators=(",", ":")).encode("utf-8")).hexdigest()
    state = _normalized_state_from_live_cps(cps_text)
    state.update({
        "active_program": SERVICE_FAILURE_AUTOMATION_PROGRAM_ID,
        "current_stop_condition": "ENGINEERING_AUTHORITY",
        "current_active_scope": "SERVICE_FAILURE_AUTOMATION_M5A_ACTION_CLASS_AUTHORITY_RECONCILIATION",
        "current_scope_class": "SERVICE_FAILURE_AUTOMATION_EVOLUTION",
        "current_state_generation": f"cpsgen_SFA_M5A_{request_fingerprint[:12].upper()}",
        "current_transition_id": "SERVICE_FAILURE_AUTOMATION_M5A_ACTION_CLASS_REQUEST_READY_V1",
        "current_next_action_id": "V7_SERVICE_FAILURE_AUTOMATION_M5A_ACTION_CLASS_AUTHORITY_DECISION",
        "current_safe_next_action": "INDEPENDENT_DECISION_ON_FRESH_ONE_USE_ACTION_CLASS_CONTRACT_REQUEST; DO NOT WRITE POLICY OR APPLY OR MOVE USERS",
        "current_program_execution_frontier": "NONE",
        "current_execution_frontier": "NONE",
        "continuation_decision": "PROGRAM_TERMINAL_ENGINEERING_AUTHORITY",
        "program_terminal_class": "ENGINEERING_AUTHORITY",
        "program_terminal_state": "ENGINEERING_AUTHORITY_ACTION_CLASS_CONTRACT_REQUEST_READY",
        "authority_required_now": "YES_FOR_CERTIFICATION_POOL_OR_DELIBERATE_CONTROLLED_CONDITION; exact one-use action-class contract decision only",
        "wip_authority_required_now": "YES_FOR_CERTIFICATION_POOL_OR_DELIBERATE_CONTROLLED_CONDITION; exact one-use action-class contract decision only",
        "wip_current_primary_stop": "ENGINEERING_AUTHORITY",
        "wip_smallest_existing_next_action_id": "V7_SERVICE_FAILURE_AUTOMATION_M5A_ACTION_CLASS_AUTHORITY_DECISION",
        "wip_smallest_existing_next_action": "V7_SERVICE_FAILURE_AUTOMATION_M5A_ACTION_CLASS_AUTHORITY_DECISION",
        "smallest_existing_next_action": "V7_SERVICE_FAILURE_AUTOMATION_M5A_ACTION_CLASS_AUTHORITY_DECISION",
        "omp_continuation_required": "FALSE",
        "external_input_required": "TRUE",
        "external_input_type": "EXACT_ACTION_CLASS_AUTHORITY_RECONCILIATION",
        "next_mission_formed": "FALSE",
        "next_mission_id": "NONE",
        "state_captured": utc_now(),
    })
    overrides = {
        "CURRENT_AUTHORITY_REQUEST_ID": f"`{request['request_id']}`",
        "CURRENT_AUTHORITY_REQUEST_HASH": f"`{request['request_hash']}`",
        "CURRENT_AUTHORITY_REQUEST_EXPIRY": f"`{request['expires_at']}`",
        "CURRENT_AUTHORITY_REQUEST_FINGERPRINT": f"`{request_fingerprint}`",
        "CURRENT_AUTHORITY_REQUEST_STATUS": "`AWAITING_INDEPENDENT_AUTHORITY_DECISION`",
        "CURRENT_AUTHORITY_REQUEST_SCOPE": "`max_users=1; max_concurrent_transactions=1`",
        "CURRENT_PACKET": "`NONE`",
        "CURRENT_LEASE": "`NONE`",
    }

    def project_m5a_predecessor_links(document: str, projected: dict[str, str]) -> str:
        """Keep the existing CAP-U07 and sequence consumers on the same CPS edge."""
        capability_section_start = "### Unfinished Capability Closure Records"
        capability_section_end = "### Open Engineering Intents And Last Responsible Links"
        sequence_start = "### Deterministic Execution Sequence"
        sequence_end = "### Authority, Reality And Safety Stops"

        def replace_one_line(text: str, start: str, end: str, prefix: str, replacement: str) -> str:
            section = _markdown_section(text, start, end)
            matches = [line for line in section.splitlines() if line.startswith(prefix)]
            if len(matches) != 1:
                raise ValueError(f"cps_projection_line_missing_or_duplicate:{prefix}")
            return text.replace(section, section.replace(matches[0], replacement, 1), 1)

        next_action = projected["current_next_action_id"]
        cap_row = (
            "| `CAP-U07` | Learning | feedback/learning, OMP, Canonical Reference | "
            "`WAITING_EXTERNAL_DEPENDENCY` | `COVERED_ENGINEERING_L4`; criterion "
            "`SHADOW_LEARNING_REPRESENTATION_MATRIX` consumed; whole capability remains PARTIAL; current M5a Authority request is "
            "read-only and does not close the capability | fresh M5a request -> existing Authority owner -> "
            "fresh planner revalidation | `ENGINEERING_AUTHORITY` | "
            f"{next_action} | U01 complete; unblocks U04/U08/U09/U12/U17-U22 |"
        )
        document = replace_one_line(
            document, capability_section_start, capability_section_end, "| `CAP-U07` |", cap_row,
        )
        sequence_row = (
            "| `1` | `U07` Learning WAITING WIP; "
            f"`{projected['current_state_generation']}`; `{projected['current_transition_id']}` | "
            "fresh M5a request is read-only; no Packet or lease exists; next scenario "
            f"`{projected['next_scenario_id']}` | `{next_action}` | "
            "existing autoswitch -> Authority owner -> fresh planner revalidation; no Runtime action | "
            "`ENGINEERING_AUTHORITY` | independent decision -> one-use contract or decline -> existing M5b consumer; "
            f"owner `{projected['program_frontier_owner']}` |"
        )
        return replace_one_line(document, sequence_start, sequence_end, "| `1` |", sequence_row)

    atomic = atomic_reconcile_cps(
        cps_path, state=state, expected_generation=expected_generation,
        request_external_wake=False, section0_field_overrides=overrides,
        document_mutator=project_m5a_predecessor_links,
    )
    return {
        "schema_version": "v7.action-class-contract-request-source-cps-reconciliation.v1",
        "final_verdict": "PASS" if atomic.get("ok") else "STOP_SAFE",
        "status": "ACTION_CLASS_CONTRACT_REQUEST_CPS_RECONCILED" if atomic.get("ok") else atomic.get("status", "STOP_SAFE"),
        "request_id": request["request_id"], "request_hash": request["request_hash"],
        "expires_at": request["expires_at"], "request_fingerprint": request_fingerprint,
        "atomic_update": atomic,
        "runtime_impact": "NONE", "routing_impact": "NONE", "user_movement": 0,
        "authority_impact": "NONE", "production_maturity_impact": "NO_CHANGE",
        "packet_created": False, "lease_created": False, "contract_written": False,
    }


def event_driven_ready_frontier_fingerprint(live: dict[str, str]) -> str:
    """Fingerprint only the owner-backed fields that make engineering work executable."""
    payload = {
        "current_execution_frontier": _plain_live_value(live, "CURRENT_EXECUTION_FRONTIER"),
        "program_execution_frontier": _plain_live_value(live, "CURRENT_PROGRAM_EXECUTION_FRONTIER"),
        "ready_capabilities": _plain_live_value(live, "READY_CAPABILITIES"),
        "next_executable_capability": _plain_live_value(live, "NEXT_EXECUTABLE_CAPABILITY"),
        "next_mission_formed": _plain_live_value(live, "NEXT_MISSION_FORMED"),
        "next_mission_id": _plain_live_value(live, "NEXT_MISSION_ID"),
        "next_scenario_id": _plain_live_value(live, "NEXT_SCENARIO_ID"),
        "active_scenario_candidate": _plain_live_value(live, "ACTIVE_SCENARIO_CANDIDATE"),
        "polygon_obligation_frontier": _plain_live_value(live, "POLYGON_OBLIGATION_FRONTIER"),
        "polygon_mission_frontier": _plain_live_value(live, "POLYGON_MISSION_FRONTIER"),
    }
    encoded = json.dumps(payload, sort_keys=True, separators=(",", ":"))
    return hashlib.sha256(encoded.encode("utf-8")).hexdigest()


def event_driven_wake_identity(
    live: dict[str, str], *, omp_version: str = EVENT_DRIVEN_OMP_VERSION,
) -> str:
    """Build a deterministic wake identity; time and randomness are deliberately excluded."""
    payload = {
        "cps_generation": _plain_live_value(live, "CURRENT_STATE_GENERATION"),
        "transition_id": _plain_live_value(live, "CURRENT_TRANSITION_ID"),
        "next_action_id": _plain_live_value(live, "CURRENT_NEXT_ACTION_ID"),
        "ready_frontier_fingerprint": event_driven_ready_frontier_fingerprint(live),
        "mission_id": _plain_live_value(live, "NEXT_MISSION_ID"),
        "candidate_id": _plain_live_value(live, "ACTIVE_SCENARIO_CANDIDATE"),
        "omp_version": omp_version,
        "external_input_required": _plain_live_value(live, "EXTERNAL_INPUT_REQUIRED"),
    }
    encoded = json.dumps(payload, sort_keys=True, separators=(",", ":"))
    return hashlib.sha256(encoded.encode("utf-8")).hexdigest()


def _event_driven_frontier_executable(live: dict[str, str]) -> bool:
    values = {
        _plain_live_value(live, "CURRENT_EXECUTION_FRONTIER"),
        _plain_live_value(live, "CURRENT_PROGRAM_EXECUTION_FRONTIER"),
        _plain_live_value(live, "READY_CAPABILITIES"),
        _plain_live_value(live, "NEXT_EXECUTABLE_CAPABILITY"),
        _plain_live_value(live, "NEXT_MISSION_ID"),
        _plain_live_value(live, "NEXT_SCENARIO_ID"),
        _plain_live_value(live, "ACTIVE_SCENARIO_CANDIDATE"),
    }
    return any(value not in {"", "NONE", "FALSE"} for value in values)


def event_driven_external_wake_request(
    previous_cps_text: str,
    current_cps_text: str,
    *,
    requested_at: Optional[datetime] = None,
    omp_version: str = EVENT_DRIVEN_OMP_VERSION,
    force_reason: Optional[str] = None,
) -> dict[str, Any]:
    """Detect one CPS transition and return a deterministic, non-blocking wake request."""
    previous = _markdown_field_table(_markdown_section(
        previous_cps_text, "## 0. Authoritative Live Current State",
        "## Authoritative Unfinished Capability Closure Registry",
    ))
    current = _markdown_field_table(_markdown_section(
        current_cps_text, "## 0. Authoritative Live Current State",
        "## Authoritative Unfinished Capability Closure Registry",
    ))
    base = {
        "schema": "v7.omp-event-driven-external-wake.v1",
        "owner": EVENT_DRIVEN_WAKE_OWNER,
        "mode": EVENT_DRIVEN_REENTRY_MODE,
        "writer_blocking": False,
        "runtime_impact": "NONE",
        "routing_impact": "NONE",
        "user_movement": "NONE",
        "authority_impact": "NONE",
        "production_maturity_impact": "NONE",
    }
    continuation = _plain_live_value(current, "OMP_CONTINUATION_REQUIRED")
    external_input = _plain_live_value(current, "EXTERNAL_INPUT_REQUIRED")
    authority = _plain_live_value(current, "AUTHORITY_REQUIRED_NOW")
    if continuation != "TRUE":
        return {**base, "outcome": "IMMEDIATE_REENTRY_NOT_REQUIRED", "dispatch_required": False, "reason": "continuation_not_required"}
    if external_input != "FALSE":
        return {**base, "outcome": "IMMEDIATE_REENTRY_SUPPRESSED_EXTERNAL_INPUT", "dispatch_required": False, "reason": "external_input_required"}
    if not authority.startswith("NO_") and authority not in {"NO", "NONE"}:
        return {**base, "outcome": "IMMEDIATE_REENTRY_SUPPRESSED_PROGRAM_TERMINAL", "dispatch_required": False, "reason": f"authority_unresolved:{authority}"}
    if _plain_live_value(current, "REENTRY_ACTIVE_LEASE") not in {"", "NONE"}:
        return {**base, "outcome": "IMMEDIATE_REENTRY_SUPPRESSED_ACTIVE_LEASE", "dispatch_required": False, "reason": "active_lease"}
    if not _event_driven_frontier_executable(current):
        return {**base, "outcome": "IMMEDIATE_REENTRY_NOT_REQUIRED", "dispatch_required": False, "reason": "ready_frontier_empty"}

    false_to_true = (
        _plain_live_value(previous, "OMP_CONTINUATION_REQUIRED") != "TRUE"
        and continuation == "TRUE"
    )
    frontier_changed = (
        event_driven_ready_frontier_fingerprint(previous)
        != event_driven_ready_frontier_fingerprint(current)
    )
    if not false_to_true and not frontier_changed and not force_reason:
        return {**base, "outcome": "IMMEDIATE_REENTRY_NOT_REQUIRED", "dispatch_required": False, "reason": "no_material_transition"}

    event_id = event_driven_wake_identity(current, omp_version=omp_version)
    if _plain_live_value(current, "LAST_DISPATCHED_WAKE_ID") == event_id:
        return {**base, "outcome": "IMMEDIATE_REENTRY_ALREADY_DISPATCHED", "dispatch_required": False, "event_id": event_id, "reason": "event_identity_consumed"}
    actual_time = requested_at or datetime.now(timezone.utc)
    if actual_time.tzinfo is None:
        actual_time = actual_time.replace(tzinfo=timezone.utc)
    return {
        **base,
        "outcome": "IMMEDIATE_REENTRY_REQUESTED",
        "dispatch_required": True,
        "event_id": event_id,
        "requested_at": actual_time.astimezone(timezone.utc).isoformat(),
        "source_cps_generation": _plain_live_value(current, "CURRENT_STATE_GENERATION"),
        "transition_id": _plain_live_value(current, "CURRENT_TRANSITION_ID"),
        "next_action_id": _plain_live_value(current, "CURRENT_NEXT_ACTION_ID"),
        "ready_frontier_fingerprint": event_driven_ready_frontier_fingerprint(current),
        "target_thread_id": HEARTBEAT_TARGET_THREAD_ID,
        "standard_entrypoint": EXTERNAL_REENTRY_STANDARD_ENTRYPOINT,
        "trigger_reasons": sorted(set(
            (["CONTINUATION_FALSE_TO_TRUE"] if false_to_true else [])
            + (["READY_FRONTIER_CHANGED"] if frontier_changed else [])
            + ([f"FORCED_REISSUE:{force_reason}"] if force_reason else [])
        )),
    }


def _event_driven_state_overrides(request: dict[str, Any]) -> dict[str, str]:
    return {
        "external_reentry_mode": EVENT_DRIVEN_REENTRY_MODE,
        "immediate_wake_owner": EVENT_DRIVEN_WAKE_OWNER,
        "last_wake_request_id": str(request["event_id"]),
        "pending_wake_id": str(request["event_id"]),
        "wake_source_cps_generation": str(request["source_cps_generation"]),
        "wake_transition_id": str(request["transition_id"]),
        "wake_requested_at": str(request["requested_at"]),
        "last_dispatched_wake_id": "NONE",
        "last_consumed_wake_id": "NONE",
        "wake_dispatched_at": "NONE",
        "wake_started_at": "NONE",
        "wake_completed_at": "NONE",
        "watchdog_state": "ARMED_PENDING_IMMEDIATE_DISPATCH",
        "immediate_last_legal_terminal": "IMMEDIATE_REENTRY_REQUESTED",
        "external_reentry_frontier": f"PENDING:{request['event_id']}",
    }


def _normalized_state_from_live_cps(cps_text: str) -> dict[str, str]:
    live_section = _markdown_section(
        cps_text, "## 0. Authoritative Live Current State",
        "## Authoritative Unfinished Capability Closure Registry",
    )
    live = _markdown_field_table(live_section)
    state = normalized_cps_live_state()
    field_aliases = {
        "aep_phase4_status": "AEP_PHASE_4_STATUS",
        "aep_phase5_status": "AEP_PHASE_5_STATUS",
        "aep_phase6_status": "AEP_PHASE_6_STATUS",
        "phase6_global_status": "PHASE_6_GLOBAL_STATUS",
        "phase6_certification_status": "PHASE_6_CERTIFICATION_STATUS",
        "phase6_current_step": "PHASE_6_CURRENT_STEP",
        "phase6_certification_frontier": "PHASE_6_CERTIFICATION_FRONTIER",
        "phase6_exact_stop": "PHASE_6_EXACT_STOP",
        "phase6_exact_next_action": "PHASE_6_EXACT_NEXT_ACTION",
        "phase6_reentry_conditions": "PHASE_6_REENTRY_CONDITIONS",
        "phase6a_scenario_status": "PHASE_6A_SCENARIO_STATUS",
        "phase6a_scenario_frontier": "PHASE_6A_SCENARIO_FRONTIER",
        "phase6a_next_scenario_id": "PHASE_6A_NEXT_SCENARIO_ID",
        "phase6a_next_action": "PHASE_6A_NEXT_ACTION",
        "phase6b_controlled_status": "PHASE_6B_CONTROLLED_STATUS",
        "phase6b_controlled_frontier": "PHASE_6B_CONTROLLED_FRONTIER",
        "phase6c_natural_status": "PHASE_6C_NATURAL_STATUS",
        "phase6_executable_frontier": "PHASE_6_EXECUTABLE_FRONTIER",
        "phase6_global_stop": "PHASE_6_GLOBAL_STOP",
        "phase6_engineering_stop": "PHASE_6_ENGINEERING_STOP",
        "phase6_controlled_lane_stop": "PHASE_6_CONTROLLED_LANE_STOP",
        "phase6_natural_lane_stop": "PHASE_6_NATURAL_LANE_STOP",
        "phase7_engineering_evolution_status": "PHASE_7_ENGINEERING_EVOLUTION_STATUS",
        "phase7_production_authority_status": "PHASE_7_PRODUCTION_AUTHORITY_STATUS",
    }
    for key in tuple(state):
        projected = field_aliases.get(key, key.upper())
        if projected in live:
            state[key] = _plain_live_value(live, projected)
    # The source call graph is the existing owner for these two footprint
    # counters.  Recompute them whenever CPS is atomically rendered so adding
    # or removing a real consumer cannot strand every later CPS writer behind
    # a stale self-referential footprint value.
    call_sites = python_function_call_sites(ROOT, "program_execution_reconciliation")
    state["program_reconciliation_real_callers"] = str(call_sites["real_caller_count"])
    state["program_reconciliation_test_callers"] = str(call_sites["test_caller_count"])
    optional_l7_l8_projection_fields = {
        "l7_l8_ae_material_outcomes": "L7_L8_AE_MATERIAL_OUTCOMES",
        "l7_l8_ae_duplicate_decision": "L7_L8_AE_DUPLICATE_DECISION",
        "l7_l8_ae_closure_projection_status": "L7_L8_AE_CLOSURE_PROJECTION_STATUS",
        "l7_l8_ae_opportunity_denominator_status": "L7_L8_AE_OPPORTUNITY_DENOMINATOR_STATUS",
        "l7_l8_ae_m1_residual": "L7_L8_AE_M1_RESIDUAL",
        "l7_l8_ae_m2_residual": "L7_L8_AE_M2_RESIDUAL",
        "l7_l8_ae_m3_residual": "L7_L8_AE_M3_RESIDUAL",
        "l7_l8_ae_m4_m8_status": "L7_L8_AE_M4_M8_STATUS",
        "l7_l8_ae_current_cycle_report": "L7_L8_AE_CURRENT_CYCLE_REPORT",
        "l7_l8_ae_current_cycle_terminal": "L7_L8_AE_CURRENT_CYCLE_TERMINAL",
        "l7_l8_ae_immutable_eligibility_set": "L7_L8_AE_IMMUTABLE_ELIGIBILITY_SET",
        "l7_l8_ae_authority_recommendation": "L7_L8_AE_AUTHORITY_RECOMMENDATION",
        "l7_l8_ae_exact_missing_cells": "L7_L8_AE_EXACT_MISSING_CELLS",
        "l7_l8_ae_next_reentry": "L7_L8_AE_NEXT_REENTRY",
        "l7_l8_ae_forbidden_effects": "L7_L8_AE_FORBIDDEN_EFFECTS",
    }
    for state_key, field_name in optional_l7_l8_projection_fields.items():
        if field_name in live:
            state[state_key] = _plain_live_value(live, field_name)
    captured = re.search(r"^Captured:\s*`([^`]+)`$", live_section, re.MULTILINE)
    if captured:
        state["state_captured"] = captured.group(1)
    header = _cps_header_metadata(cps_text)
    if header.get("Source"):
        state["source_summary"] = header["Source"]
    registry = _markdown_field_table(_markdown_section(
        cps_text, "### Registry Metadata And Truth Lifecycle",
        "### Active Protected Work In Progress",
    ))
    wip = _markdown_field_table(_markdown_section(
        cps_text, "### Active Protected Work In Progress",
        "### Complete Or Locked Capability Records",
    ))
    # These owner fields are not duplicated in Section 0.  Reconstructing a
    # transition from the live CPS must preserve them instead of inheriting the
    # process's newer module defaults, otherwise a valid historical/active
    # frontier is rewritten with a mismatched capability action.
    state["wip_smallest_existing_next_action_id"] = _plain_live_value(
        wip, "smallest_existing_next_action_id",
    ) or _plain_live_value(registry, "EXACT_CURRENT_SMALLEST_NEXT_ACTION")
    state["wip_authority_required_now"] = (
        _plain_live_value(wip, "authority_required_now")
        or state["wip_authority_required_now"]
    )
    state["wip_current_primary_stop"] = (
        _plain_live_value(wip, "current_primary_stop")
        or state["wip_current_primary_stop"]
    )
    registry_next = _plain_live_value(registry, "EXACT_CURRENT_SMALLEST_NEXT_ACTION")
    state["wip_smallest_existing_next_action"] = (
        wip.get("smallest_existing_next_action", "").strip("`")
        or f"{registry_next}; preserve CAP-U07 natural-evidence WIP"
    )
    state["last_responsible_link"] = (
        wip.get("last_responsible_link", "").strip()
        or state["last_responsible_link"]
    )
    state["omp_continuation_pointer"] = (
        registry.get("OMP_CONTINUATION_POINTER", "").strip("`")
        or state["omp_continuation_pointer"]
    )
    state["smallest_existing_next_action"] = (
        _plain_live_value(registry, "EXACT_CURRENT_SMALLEST_NEXT_ACTION")
        or state["smallest_existing_next_action"]
    )
    for key, suffix in (
        ("binding_stability", "; 22 post-deploy read-only cycles"),
        ("binding_schema", "; shared by preview, admission and low-level pre-mutation recheck"),
        ("routing_readiness_state", "; global inventory diagnostics are advisory_only and no longer cross-scope blockers"),
    ):
        state[key] = state[key].split(suffix, 1)[0]
    sequence = _markdown_section(
        cps_text, "### Deterministic Execution Sequence", "### Authority, Reality And Safety Stops",
    )
    rows = [line for line in sequence.splitlines() if line.startswith("| `1` |")]
    if len(rows) == 1:
        cells = [cell.strip() for cell in rows[0].strip().strip("|").split("|")]
        if len(cells) >= 7:
            state["program_frontier_input"] = cells[2]
            state["program_frontier_expected_output"] = cells[6]
            if state["current_program_execution_frontier"] not in {"", "NONE"}:
                state["program_frontier_owner"] = cells[4]
            elif "; " in cells[4]:
                state["sequence_execution_class"], state["program_frontier_owner"] = cells[4].rsplit("; ", 1)
    return state


def event_driven_wake_lifecycle(
    path: Path,
    *,
    event_id: str,
    phase: str,
    occurred_at: Optional[datetime] = None,
) -> dict[str, Any]:
    """Persist dispatch failure/success without invoking OMP or changing Runtime."""
    if not re.fullmatch(r"[0-9a-f]{64}", event_id):
        return {"final_verdict": "STOP_SAFE", "outcome": "IMMEDIATE_REENTRY_FAILED_SAFE", "errors": ["event_identity_invalid"]}
    try:
        cps_text = path.read_text(encoding="utf-8")
    except OSError as exc:
        return {"final_verdict": "STOP_SAFE", "outcome": "IMMEDIATE_REENTRY_FAILED_SAFE", "errors": [f"cps_unreadable:{exc}"]}
    state = _normalized_state_from_live_cps(cps_text)
    if state["last_dispatched_wake_id"] == event_id and phase.upper() == "DISPATCHED":
        state["immediate_duplicate_suppression_count"] = str(int(state["immediate_duplicate_suppression_count"] or "0") + 1)
        result = atomic_reconcile_cps(path, state=state)
        return {
            "final_verdict": "PASS" if result.get("ok") else "STOP_SAFE",
            "outcome": "IMMEDIATE_REENTRY_ALREADY_DISPATCHED",
            "event_id": event_id,
            "atomic_update": result,
            "errors": result.get("errors") or [],
        }
    if state["pending_wake_id"] != event_id:
        return {"final_verdict": "STOP_SAFE", "outcome": "IMMEDIATE_REENTRY_FAILED_SAFE", "errors": ["pending_event_identity_mismatch"]}
    actual = occurred_at or datetime.now(timezone.utc)
    if actual.tzinfo is None:
        actual = actual.replace(tzinfo=timezone.utc)
    timestamp = actual.astimezone(timezone.utc).isoformat()
    normalized_phase = phase.upper()
    if normalized_phase == "DISPATCHED":
        state.update({
            "last_dispatched_wake_id": event_id,
            "wake_dispatched_at": timestamp,
            "watchdog_state": "ARMED_DISPATCHED_AWAITING_CONSUMER",
            "immediate_last_legal_terminal": "IMMEDIATE_REENTRY_DISPATCHED",
        })
        outcome = "IMMEDIATE_REENTRY_DISPATCHED"
    elif normalized_phase == "FAILED":
        state.update({
            "last_dispatched_wake_id": "NONE",
            "wake_dispatched_at": "NONE",
            "watchdog_state": "PENDING_WATCHDOG_RECOVERY",
            "immediate_last_legal_terminal": "IMMEDIATE_REENTRY_FAILED_SAFE",
        })
        outcome = "IMMEDIATE_REENTRY_FAILED_SAFE"
    else:
        return {"final_verdict": "STOP_SAFE", "outcome": "IMMEDIATE_REENTRY_FAILED_SAFE", "errors": ["lifecycle_phase_invalid"]}
    result = atomic_reconcile_cps(path, state=state)
    return {
        "schema": "v7.omp-event-driven-wake-lifecycle.v1",
        "final_verdict": "PASS" if result.get("ok") else "STOP_SAFE",
        "outcome": outcome if result.get("ok") else "IMMEDIATE_REENTRY_FAILED_SAFE",
        "event_id": event_id,
        "occurred_at": timestamp,
        "writer_blocking": False,
        "atomic_update": result,
        "runtime_impact": "NONE",
        "routing_impact": "NONE",
        "user_movement": "NONE",
        "authority_impact": "NONE",
        "errors": result.get("errors") or [],
    }


def heartbeat_dependency_fingerprint(cps_text: str) -> str:
    """Fingerprint the owner-backed dependency graph consumed by the heartbeat."""
    graph = _markdown_section(
        cps_text,
        "### Capability Dependency Graph And Execution Frontier",
        "### Owner Revalidation Requirements And Contradictions",
    )
    return hashlib.sha256(graph.encode("utf-8")).hexdigest()


def _matrix_runtime_successor_is_explicit(live: dict[str, str]) -> bool:
    """True only for the existing Matrix-owned active-incident continuation."""
    value = lambda key: _plain_live_value(live, key)
    return all((
        value("ACTIVE_PROGRAM") == SERVICE_FAILURE_AUTOMATION_PROGRAM_ID,
        value("CURRENT_NEXT_ACTION_ID") == "CONTINUE_ACTIVE_INCIDENT_REVALIDATION_AND_DRAIN",
        value("CURRENT_PROGRAM_EXECUTION_FRONTIER") == "CONTINUE_ACTIVE_INCIDENT_REVALIDATION_AND_DRAIN",
    ))


def _external_reentry_lease_path(root: Path) -> Path:
    identity = hashlib.sha256(str(root.resolve()).encode("utf-8")).hexdigest()[:16]
    return Path(tempfile.gettempdir()) / f"v7-omp-external-reentry-{identity}.lease.json"


def _external_reentry_evidence_path(root: Path) -> Path:
    return root / "docs/reports/engineering/evidence/V7_OMP_EXTERNAL_REENTRY_RUNS.jsonl"


def _external_reentry_eligibility(live: dict[str, str]) -> dict[str, Any]:
    """Evaluate the fresh-CPS, no-authority external reentry contract."""
    value = lambda key: live.get(key, "").strip("`")
    if value("OMP_CONTINUATION_REQUIRED") != "TRUE":
        return {"eligible": False, "outcome": "REENTRY_NOT_REQUIRED", "reason": "continuation_not_required"}
    if value("EXTERNAL_INPUT_REQUIRED") != "FALSE":
        return {"eligible": False, "outcome": "REENTRY_BLOCKED_EXTERNAL_INPUT", "reason": value("EXTERNAL_INPUT_TYPE") or "external_input_required"}
    authority = value("AUTHORITY_REQUIRED_NOW")
    if not authority.startswith("NO_") and authority not in {"NO", "NONE"}:
        return {"eligible": False, "outcome": "REENTRY_BLOCKED_PROGRAM_TERMINAL", "reason": f"authority_unresolved:{authority}"}
    program_terminal = value("PROGRAM_TERMINAL_CLASS")
    if program_terminal in {
        "OPERATIONAL_AUTHORITY_OUTSIDE_ACTIVE_POLICY", "NON_DETERMINISTIC_DECISION",
        "SECURITY_OR_ACCESS_INPUT", "FUNDAMENTAL_EXTERNAL_REENTRY_PLATFORM_GAP",
    }:
        return {"eligible": False, "outcome": "REENTRY_BLOCKED_PROGRAM_TERMINAL", "reason": program_terminal}
    active_id = value("CURRENT_EXECUTION_MISSION_ID")
    active_state = value("CURRENT_EXECUTION_MISSION_STATE")
    if active_id not in {"", "NONE"} or active_state not in {"", "NONE"}:
        return {"eligible": False, "outcome": "REENTRY_ALREADY_ACTIVE", "reason": f"active_mission:{active_id}:{active_state}"}
    active_frontier = value("ACTIVE_EXECUTION_FRONTIER")
    if active_frontier not in {"", "NONE"}:
        return {
            "eligible": False,
            "outcome": "REENTRY_ALREADY_ACTIVE",
            "reason": f"active_execution_frontier:{active_frontier}",
        }
    executable_frontier = value("CURRENT_PROGRAM_EXECUTION_FRONTIER")
    continue_omp_selected = (
        value("CURRENT_NEXT_ACTION_ID") == "CONTINUE_OMP"
        or value("NEXT_MISSION_ID") == "CONTINUE_OMP"
        or executable_frontier not in {"", "NONE"}
    )
    if not continue_omp_selected:
        return {"eligible": False, "outcome": "REENTRY_NOT_REQUIRED", "reason": "next_action_not_continue_omp"}
    if not value("CURRENT_STATE_GENERATION"):
        return {"eligible": False, "outcome": "REENTRY_FAILED_SAFE", "reason": "cps_generation_missing"}
    if program_terminal in {"", "NONE"} and executable_frontier in {"", "NONE"}:
        return {"eligible": False, "outcome": "REENTRY_ALREADY_ACTIVE", "reason": "previous_invocation_not_terminal"}
    return {
        "eligible": True,
        "outcome": "REENTRY_ACQUIRED",
        "reason": "fresh_cps_executable_frontier_eligible",
        "cps_generation": value("CURRENT_STATE_GENERATION"),
    }


def _external_reentry_acquire_lease(
    *, lease_path: Path, lease_id: str, event_id: str, cps_generation: str,
    now: datetime, owner: str = "CODEX_AUTOMATION_PLATFORM",
) -> dict[str, Any]:
    """Acquire a single-flight lease with bounded stale/process-death recovery."""
    lease_path.parent.mkdir(parents=True, exist_ok=True)
    recovered: Optional[dict[str, Any]] = None
    for _attempt in range(2):
        expires = now + timedelta(seconds=EXTERNAL_REENTRY_LEASE_TTL_SECONDS)
        record = {
            "schema": "v7.omp-external-reentry-lease.v1", "lease_id": lease_id,
            "event_id": event_id, "owner": owner, "pid": os.getpid(),
            "cps_generation": cps_generation, "started_at": now.isoformat(),
            "expires_at": expires.isoformat(),
        }
        try:
            descriptor = os.open(str(lease_path), os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
        except FileExistsError:
            try:
                existing = json.loads(lease_path.read_text(encoding="utf-8"))
                expiry = _parse_iso_timestamp(str(existing.get("expires_at", "")))
            except (OSError, ValueError, TypeError, json.JSONDecodeError):
                existing = {"lease_id": "UNKNOWN", "expires_at": "UNKNOWN"}
                try:
                    expiry = datetime.fromtimestamp(lease_path.stat().st_mtime, timezone.utc) + timedelta(seconds=EXTERNAL_REENTRY_LEASE_TTL_SECONDS)
                except OSError:
                    expiry = now + timedelta(seconds=EXTERNAL_REENTRY_LEASE_TTL_SECONDS)
            if expiry > now:
                return {"acquired": False, "outcome": "REENTRY_ALREADY_ACTIVE", "active_lease": existing, "stale_recovered": False}
            try:
                lease_path.unlink()
            except FileNotFoundError:
                pass
            except OSError as exc:
                return {"acquired": False, "outcome": "REENTRY_FAILED_SAFE", "errors": [f"stale_lease_unlink_failed:{exc}"]}
            recovered = existing
            continue
        try:
            with os.fdopen(descriptor, "w", encoding="utf-8") as handle:
                json.dump(record, handle, ensure_ascii=False, sort_keys=True)
                handle.write("\n")
                handle.flush()
                os.fsync(handle.fileno())
        except OSError as exc:
            with contextlib.suppress(OSError):
                lease_path.unlink()
            return {"acquired": False, "outcome": "REENTRY_FAILED_SAFE", "errors": [f"lease_write_failed:{exc}"]}
        return {
            "acquired": True,
            "outcome": "REENTRY_STALE_LEASE_RECOVERED" if recovered else "REENTRY_ACQUIRED",
            "lease": record, "stale_recovered": recovered is not None, "recovered_lease": recovered,
        }
    return {"acquired": False, "outcome": "REENTRY_FAILED_SAFE", "errors": ["lease_acquire_retry_exhausted"]}


def _external_reentry_run_standard_entrypoint(root: Path) -> dict[str, Any]:
    command = [
        str(root / "tools/v7-truth-check"), "--continue-omp",
        "--continue-omp-persist-cps", "--json",
    ]
    try:
        completed = subprocess.run(
            command, cwd=str(root), text=True, capture_output=True,
            timeout=FUTURE_SCALE_EXECUTION_MAX_SECONDS + 60, check=False,
        )
    except (OSError, subprocess.TimeoutExpired) as exc:
        return {"final_verdict": "STOP_SAFE", "errors": [f"standard_entrypoint_failed:{exc}"]}
    try:
        payload = json.loads(completed.stdout)
    except json.JSONDecodeError:
        payload = {
            "final_verdict": "STOP_SAFE", "errors": ["standard_entrypoint_non_json_output"],
            "returncode": completed.returncode, "stderr": completed.stderr[-2000:],
        }
    payload["subprocess_returncode"] = completed.returncode
    payload["exact_entrypoint"] = EXTERNAL_REENTRY_STANDARD_ENTRYPOINT
    return payload


def _append_external_reentry_evidence(path: Path, record: dict[str, Any]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open("a", encoding="utf-8") as handle:
        fcntl.flock(handle.fileno(), fcntl.LOCK_EX)
        handle.write(json.dumps(record, ensure_ascii=False, sort_keys=True) + "\n")
        handle.flush()
        os.fsync(handle.fileno())
        fcntl.flock(handle.fileno(), fcntl.LOCK_UN)


def external_reentry_completion_evidence_gate(
    runs: Iterable[dict[str, Any]], *, automation_enabled: bool,
    fsse04_deployed: bool, truth_passed: bool, convergence_passed: bool,
    snapshot_equal: bool,
) -> dict[str, Any]:
    """Certify two owner-backed post-context reentries; labels alone never pass."""
    records = list(runs)
    independent = [
        run for run in records
        if run.get("platform_owner") == "CODEX_AUTOMATION_PLATFORM"
        and run.get("no_user_prompt") is True
        and run.get("prior_context_exited") is True
        and run.get("standard_entrypoint_invoked") is True
        and run.get("consumer_invoked") is True
        and run.get("lease_released") is True
        and run.get("no_overlap") is True
        and run.get("reentry_outcome") in {"REENTRY_COMPLETED", "REENTRY_NOT_REQUIRED"}
    ]
    unique_events = {run.get("event_id") for run in independent if run.get("event_id")}
    unique_invocations = {run.get("invocation_id") for run in independent if run.get("invocation_id")}
    separated = len(independent) >= 2 and len(unique_events) >= 2 and len(unique_invocations) >= 2
    behavior = bool(independent and independent[0].get("behavior_change") is True)
    later_terminal = separated and bool(
        independent[1].get("behavior_change") is True
        or independent[1].get("reentry_outcome") == "REENTRY_NOT_REQUIRED"
    )
    checks = {
        "FSSE04_DEPLOYED": fsse04_deployed,
        "AUTOMATION_ENABLED": automation_enabled,
        "TWO_SEPARATED_EXTERNAL_REENTRIES": separated,
        "FIRST_REENTRY_BEHAVIOR_CHANGE": behavior,
        "LATER_REENTRY_CONTINUED_OR_LEGAL_TERMINAL": later_terminal,
        "TRUTH_PASS": truth_passed,
        "CONVERGENCE_PASS": convergence_passed,
        "SNAPSHOT_EQUAL": snapshot_equal,
    }
    missing = [key for key, passed in checks.items() if not passed]
    return {
        "schema": "v7.omp-external-reentry-completion-gate.v1",
        "completion_contract": "AUTOMATION_COMPLETION",
        "independent_reentry_count": len(independent),
        "unique_event_count": len(unique_events),
        "unique_invocation_count": len(unique_invocations),
        "checks": checks, "missing_evidence": missing,
        "completion_verdict": "PASS" if not missing else "INCOMPLETE",
        "target_terminal": (
            "FULL_INDEPENDENT_BACKGROUND_AUTOMATION_PRODUCTION_CERTIFIED"
            if not missing else "NOT_CERTIFIED"
        ),
    }


def heartbeat_program_reentry(
    *,
    event_time: str,
    automation_id: str = HEARTBEAT_AUTOMATION_ID,
    target_thread_id: str = HEARTBEAT_TARGET_THREAD_ID,
    project_id: str = "",
    target_capability: str = "CAP-U07",
    evidence_freshness_result: str = "PASS",
    evidence_sufficiency_result: str = "INSUFFICIENT",
    seen_event_ids: Optional[Iterable[str]] = None,
    seen_wakeup_run_ids: Optional[Iterable[str]] = None,
    execute_continue_omp: bool = False,
    continue_runner: Optional[Callable[[Path], dict[str, Any]]] = None,
    lease_path: Optional[Path] = None,
    evidence_path: Optional[Path] = None,
    now: Optional[datetime] = None,
    event_identity_override: str = "",
    event_source_kind: str = "HEARTBEAT_WATCHDOG",
    root: Path = ROOT,
) -> dict[str, Any]:
    """Run the existing heartbeat owner; optionally perform independent OMP reentry."""
    resolved_project = project_id or str(root)
    normalized_time = event_time[:-1] + "+00:00" if event_time.endswith("Z") else event_time
    try:
        _parse_iso_timestamp(normalized_time)
    except (TypeError, ValueError):
        return {
            "schema": "v7-omp-heartbeat-program-reentry/v1",
            "final_verdict": "STOP_SAFE",
            "errors": ["heartbeat_event_time_invalid"],
            "runtime_impact": "NONE",
            "production_impact": "NONE",
            "authority_impact": "NONE",
        }

    try:
        sources = load_program_execution_sources(root)
    except OSError as exc:
        return {
            "schema": "v7-omp-heartbeat-program-reentry/v1",
            "final_verdict": "STOP_SAFE",
            "errors": [f"program_execution_source_unreadable:{exc}"],
            "runtime_impact": "NONE",
            "production_impact": "NONE",
            "authority_impact": "NONE",
        }

    cps_text = sources["cps"]
    live = _markdown_field_table(_markdown_section(
        cps_text,
        "## 0. Authoritative Live Current State",
        "## Authoritative Unfinished Capability Closure Registry",
    ))
    current_generation = live.get("CURRENT_STATE_GENERATION", "").strip("`")
    pending_wake_id = _plain_live_value(live, "PENDING_WAKE_ID")
    last_dispatched_wake_id = _plain_live_value(live, "LAST_DISPATCHED_WAKE_ID")
    watchdog_recovery = False
    if execute_continue_omp and not event_identity_override and pending_wake_id not in {"", "NONE"}:
        recovery_pending = _plain_live_value(live, "WATCHDOG_STATE") == "PENDING_WATCHDOG_RECOVERY"
        if last_dispatched_wake_id == pending_wake_id and not recovery_pending:
            # A pre-acknowledgement process from an older binary may have
            # exited after acquiring its local lease but before it could
            # record completion.  When the lease is absent and the only live
            # successor is the already-deployed Matrix continuation, clear
            # that stale bridge state atomically.  We do not rerun OMP or
            # schedule another wake: Matrix remains the existing owner.
            resolved_lease_path = lease_path or _external_reentry_lease_path(root)
            if _matrix_runtime_successor_is_explicit(live) and not resolved_lease_path.exists():
                acknowledged_at = datetime.now(timezone.utc)
                acknowledgement_generation = f"cpsgen_V7_MATRIX_ACK_{pending_wake_id[:12].upper()}"
                acknowledgement_state = normalized_cps_live_state({
                    **_normalized_state_from_live_cps(cps_text),
                    "state_captured": acknowledged_at.isoformat(),
                    "current_state_generation": acknowledgement_generation,
                    "current_transition_id": "MATRIX_RUNTIME_SUCCESSOR_ACKNOWLEDGED_V1",
                    "reentry_active_lease": "NONE",
                    "reentry_last_completed_id": f"matrixack_{pending_wake_id[:24]}",
                    "reentry_platform_health": "PASS",
                    "last_consumed_wake_id": pending_wake_id,
                    "pending_wake_id": "NONE",
                    "wake_started_at": _plain_live_value(live, "WAKE_STARTED_AT") or acknowledged_at.isoformat(),
                    "wake_completed_at": acknowledged_at.isoformat(),
                    "watchdog_state": "ARMED_FALLBACK_ONLY",
                    "immediate_last_legal_terminal": "MATRIX_RUNTIME_SUCCESSOR_ACKNOWLEDGED",
                })
                acknowledgement = atomic_reconcile_cps(
                    root / "docs/programs/V7_CURRENT_PROGRAM_STATE.md",
                    state=acknowledgement_state,
                    request_external_wake=False,
                    expected_generation=current_generation,
                    section0_field_overrides={
                        "CURRENT_SERVICE_FAILURE_NEXT_REQUIRED_CONSUMER": "`tools/v7-service-matrix-refresh-all`",
                        "CURRENT_SERVICE_FAILURE_REENTRY_CONDITION": "`enabled v7-service-matrix-refresh.timer performs fresh observation and consumes the durable active-incident successor`",
                    },
                )
                return {
                    "schema": "v7-omp-event-driven-watchdog/v1",
                    "event_id": pending_wake_id,
                    "reentry_outcome": "MATRIX_RUNTIME_SUCCESSOR_ACKNOWLEDGED" if acknowledgement.get("ok") else "REENTRY_FAILED_SAFE",
                    "standard_entrypoint_invoked": False,
                    "consumer_invoked": bool(acknowledgement.get("ok")),
                    "matrix_owned_incident_drain": True,
                    "watchdog_fallback": False,
                    "atomic_update": acknowledgement,
                    "final_verdict": "PASS" if acknowledgement.get("ok") else "STOP_SAFE",
                    "runtime_impact": "NONE", "production_impact": "NONE", "authority_impact": "NONE",
                    "errors": acknowledgement.get("errors") or [],
                }
            return {
                "schema": "v7-omp-event-driven-watchdog/v1",
                "event_id": pending_wake_id,
                "reentry_outcome": "IMMEDIATE_REENTRY_ALREADY_DISPATCHED",
                "standard_entrypoint_invoked": False,
                "consumer_invoked": False,
                "watchdog_fallback": False,
                "final_verdict": "PASS",
                "runtime_impact": "NONE", "production_impact": "NONE", "authority_impact": "NONE",
                "errors": [],
            }
        event_identity_override = pending_wake_id
        event_source_kind = "WATCHDOG_LOST_WAKE_RECOVERY"
        watchdog_recovery = True
    current_dependency = heartbeat_dependency_fingerprint(cps_text)
    previous_dependency = live.get("HEARTBEAT_LAST_DEPENDENCY_FINGERPRINT", "").strip("`")
    if not re.fullmatch(r"[0-9a-f]{64}", previous_dependency):
        previous_dependency = current_dependency

    if seen_event_ids is None:
        last_event_id = live.get("HEARTBEAT_LAST_EVENT_ID", "").strip("`")
        seen_event_ids = (
            [] if watchdog_recovery
            else [last_event_id] if re.fullmatch(r"[0-9a-f]{64}", last_event_id) else []
        )
    if watchdog_recovery and seen_wakeup_run_ids is None:
        seen_wakeup_run_ids = []

    if event_identity_override and not re.fullmatch(r"[0-9a-f]{64}", event_identity_override):
        return {
            "schema": "v7-omp-external-reentry/v1", "final_verdict": "STOP_SAFE",
            "reentry_outcome": "IMMEDIATE_REENTRY_FAILED_SAFE",
            "standard_entrypoint_invoked": False, "consumer_invoked": False,
            "errors": ["event_identity_override_invalid"],
            "runtime_impact": "NONE", "production_impact": "NONE", "authority_impact": "NONE",
        }
    event_identity = event_identity_override or hashlib.sha256(
        f"{automation_id}|{target_thread_id}|{normalized_time}".encode("utf-8")
    ).hexdigest()
    wakeup_prefix = "ew" if event_identity_override else "hb"
    wakeup_run_id = f"{wakeup_prefix}_{event_identity[:32]}"
    contract = {
        "AUTOMATION_ID": automation_id,
        "TARGET_THREAD_ID": target_thread_id,
        "PROJECT_ID": resolved_project,
        "WAKEUP_RUN_ID": wakeup_run_id,
        "EVENT_ID": event_identity,
        "EVENT_OWNER": "CODEX_AUTOMATION_PLATFORM",
        "EVENT_SOURCE": f"CODEX_AUTOMATION_PLATFORM:{event_source_kind.lower()}:{automation_id}:{wakeup_run_id}",
        "EVENT_GENERATION": current_generation,
        "EVENT_TIME": normalized_time,
        "FRESHNESS_RULE": "FRESH_PLATFORM_EVENT_AND_FRESH_CPS_READ",
        "DEPENDENCY_FINGERPRINT_BEFORE": previous_dependency,
        "DEPENDENCY_FINGERPRINT_AFTER": current_dependency,
        "DEPENDENCY_CHANGED": previous_dependency != current_dependency,
        "TARGET_CAPABILITY": target_capability,
        "CURRENT_CPS_GENERATION": current_generation,
        "MISSION_SCOPE": "EXTERNAL_STANDARD_CONTINUE_OMP_REENTRY" if execute_continue_omp else "HEARTBEAT_REENTRY_DRY_RUN_ONLY",
        "AUTHORIZATION_SCOPE": "ENGINEERING_EXTERNAL_REENTRY_ONLY" if execute_continue_omp else "START_ENGINEERING_EXECUTION_CONTEXT_ONLY",
        "REPLAY_PROTECTION": "MISSION_IDENTITY+CPS_GENERATION+EVENT_ID+WAKEUP_RUN_ID+DEPENDENCY_FINGERPRINT",
        "CONCURRENCY_CONTROL": "CURRENT_EXECUTION_MISSION_ID+CURRENT_EXECUTION_MISSION_STATE+CURRENT_STATE_GENERATION",
        "ACTIVATION_RESULT": "PENDING_DRY_RUN",
        "EVIDENCE_FRESHNESS_RESULT": evidence_freshness_result,
        "EVIDENCE_SUFFICIENCY_RESULT": evidence_sufficiency_result,
        "NO_RUNTIME_AUTHORITY": True,
        "NO_USER_MOVEMENT_AUTHORITY": True,
        "NO_PACKET_AUTHORITY": True,
        "NO_CANDIDATE_AUTHORITY": True,
    }
    adapter = heartbeat_boundary_dry_run(
        cps_text,
        contract,
        expected_automation_id=HEARTBEAT_AUTOMATION_ID,
        expected_target_thread_id=HEARTBEAT_TARGET_THREAD_ID,
        expected_project_id=str(root),
        seen_event_ids=seen_event_ids,
        seen_wakeup_run_ids=seen_wakeup_run_ids,
    )
    activation = adapter["activation_result"]
    if execute_continue_omp:
        pre_eligibility = _external_reentry_eligibility(live)
        if not pre_eligibility["eligible"]:
            return {
                "schema": "v7-omp-external-reentry/v1", "event_id": event_identity,
                "wakeup_run_id": wakeup_run_id, "fresh_cps_generation": current_generation,
                "adapter": adapter, "eligibility": pre_eligibility,
                "reentry_outcome": pre_eligibility["outcome"], "standard_entrypoint_invoked": False,
                "consumer_invoked": False, "final_verdict": "PASS",
                "runtime_impact": "NONE", "production_impact": "NONE", "authority_impact": "NONE",
                "errors": [],
            }
    skip_reconciliation = activation in {
        "NO_CHANGE_DUPLICATE_WAKEUP",
        "NO_CHANGE_ALREADY_ACTIVE",
        "STOP_SAFE_IDENTITY_FAILURE",
        "STOP_SAFE_REPLAY_FAILURE",
    }
    if skip_reconciliation:
        return {
            "schema": "v7-omp-heartbeat-program-reentry/v1",
            "event_id": event_identity,
            "wakeup_run_id": wakeup_run_id,
            "fresh_cps_generation": current_generation,
            "dependency_fingerprint": current_dependency,
            "adapter": adapter,
            "reconciliation_invoked": False,
            "consumer_invoked": False,
            "standard_entrypoint_invoked": False,
            "reentry_outcome": "REENTRY_ALREADY_ACTIVE" if activation == "NO_CHANGE_ALREADY_ACTIVE" else "REENTRY_NOT_REQUIRED",
            "legal_terminal": activation.startswith("NO_CHANGE"),
            "next_output": activation,
            "final_verdict": adapter["final_verdict"],
            "runtime_impact": "NONE",
            "production_impact": "NONE",
            "authority_impact": "NONE",
            "errors": adapter["errors"],
        }

    if execute_continue_omp:
        eligibility = pre_eligibility
        actual_now = now or datetime.now(timezone.utc)
        if actual_now.tzinfo is None:
            actual_now = actual_now.replace(tzinfo=timezone.utc)
        actual_now = actual_now.astimezone(timezone.utc)
        invocation_id = f"ompre_{hashlib.sha256(f'{event_identity}|{current_generation}'.encode()).hexdigest()[:24]}"
        lease_id = f"omplease_{hashlib.sha256(f'{invocation_id}|{os.getpid()}'.encode()).hexdigest()[:24]}"
        resolved_lease_path = lease_path or _external_reentry_lease_path(root)
        lease_result = _external_reentry_acquire_lease(
            lease_path=resolved_lease_path, lease_id=lease_id, event_id=event_identity,
            cps_generation=current_generation, now=actual_now,
        )
        if not lease_result.get("acquired"):
            return {
                "schema": "v7-omp-external-reentry/v1", "event_id": event_identity,
                "wakeup_run_id": wakeup_run_id, "fresh_cps_generation": current_generation,
                "adapter": adapter, "eligibility": eligibility, "lease": lease_result,
                "reentry_outcome": lease_result.get("outcome", "REENTRY_FAILED_SAFE"),
                "standard_entrypoint_invoked": False, "consumer_invoked": False,
                "final_verdict": "PASS" if lease_result.get("outcome") == "REENTRY_ALREADY_ACTIVE" else "STOP_SAFE",
                "runtime_impact": "NONE", "production_impact": "NONE", "authority_impact": "NONE",
                "errors": lease_result.get("errors") or [],
            }
        lease_released = False
        result: dict[str, Any]
        try:
            fresh_text = (root / "docs/programs/V7_CURRENT_PROGRAM_STATE.md").read_text(encoding="utf-8")
            fresh_live = _markdown_field_table(_markdown_section(
                fresh_text, "## 0. Authoritative Live Current State",
                "## Authoritative Unfinished Capability Closure Registry",
            ))
            if fresh_live.get("CURRENT_STATE_GENERATION", "").strip("`") != current_generation:
                result = {
                    "schema": "v7-omp-external-reentry/v1", "reentry_outcome": "REENTRY_FAILED_SAFE",
                    "final_verdict": "STOP_SAFE", "errors": ["cps_generation_compare_and_set_failed"],
                    "standard_entrypoint_invoked": False, "consumer_invoked": False,
                }
            else:
                certified_baseline = (
                    fresh_live.get("BACKGROUND_AUTOMATION_STATE", "").strip("`")
                    == "FULL_INDEPENDENT_BACKGROUND_AUTOMATION_PRODUCTION_CERTIFIED"
                )
                reentry_background_state = (
                    "FULL_INDEPENDENT_BACKGROUND_AUTOMATION_PRODUCTION_CERTIFIED"
                    if certified_baseline else "EXTERNAL_REENTRY_ACTIVE_AWAITING_TWO_NATURAL_RUNS"
                )
                active_generation = f"cpsgen_V7_REENTRY_ACTIVE_{event_identity[:12].upper()}"
                active_state = normalized_cps_live_state({
                    **_normalized_state_from_live_cps(fresh_text),
                    "state_captured": actual_now.isoformat(),
                    "current_state_generation": active_generation,
                    "current_transition_id": "EXTERNAL_REENTRY_LEASE_ACQUIRED_V1",
                    "heartbeat_status": "ACTIVE", "automation_enabled": "TRUE",
                    "heartbeat_automation_level": "EXTERNAL_STANDARD_CONTINUE_OMP_REENTRY_ACTIVE",
                    "background_automation_state": reentry_background_state,
                    "external_reentry_enabled": "TRUE", "reentry_active_lease": lease_id,
                    "reentry_last_trigger_id": event_identity, "reentry_last_trigger_at": actual_now.isoformat(),
                    "reentry_last_invocation_id": invocation_id, "reentry_platform_health": "ACTIVE",
                    "external_reentry_mode": EVENT_DRIVEN_REENTRY_MODE,
                    "event_driven_external_reentry_status": _plain_live_value(fresh_live, "EVENT_DRIVEN_EXTERNAL_REENTRY_STATUS"),
                    "heartbeat_role": "WATCHDOG_FALLBACK",
                    "immediate_wake_owner": EVENT_DRIVEN_WAKE_OWNER,
                    "last_wake_request_id": _plain_live_value(fresh_live, "LAST_WAKE_REQUEST_ID"),
                    "last_dispatched_wake_id": event_identity if event_identity_override else _plain_live_value(fresh_live, "LAST_DISPATCHED_WAKE_ID"),
                    "last_consumed_wake_id": _plain_live_value(fresh_live, "LAST_CONSUMED_WAKE_ID"),
                    "pending_wake_id": event_identity if event_identity_override else _plain_live_value(fresh_live, "PENDING_WAKE_ID"),
                    "wake_source_cps_generation": _plain_live_value(fresh_live, "WAKE_SOURCE_CPS_GENERATION"),
                    "wake_transition_id": _plain_live_value(fresh_live, "WAKE_TRANSITION_ID"),
                    "wake_requested_at": _plain_live_value(fresh_live, "WAKE_REQUESTED_AT"),
                    "wake_dispatched_at": (
                        actual_now.isoformat()
                        if watchdog_recovery else
                        _plain_live_value(fresh_live, "WAKE_DISPATCHED_AT")
                        if _plain_live_value(fresh_live, "WAKE_DISPATCHED_AT") not in {"", "NONE"}
                        else actual_now.isoformat()
                    ),
                    "wake_started_at": actual_now.isoformat(),
                    "wake_completed_at": "NONE",
                    "writer_blocking_time_ms": _plain_live_value(fresh_live, "WRITER_BLOCKING_TIME_MS"),
                    "watchdog_state": "WATCHDOG_RECOVERY_RUNNING" if watchdog_recovery else "IMMEDIATE_CONSUMER_RUNNING",
                    "watchdog_fallback_count": _plain_live_value(fresh_live, "WATCHDOG_FALLBACK_COUNT") or "0",
                    "watchdog_recovery_result": _plain_live_value(fresh_live, "WATCHDOG_RECOVERY_RESULT"),
                    "immediate_invocation_count": _plain_live_value(fresh_live, "IMMEDIATE_INVOCATION_COUNT") or "0",
                    "immediate_duplicate_suppression_count": _plain_live_value(fresh_live, "IMMEDIATE_DUPLICATE_SUPPRESSION_COUNT") or "0",
                    "overlap_count": _plain_live_value(fresh_live, "OVERLAP_COUNT") or "0",
                    "immediate_last_legal_terminal": "IMMEDIATE_REENTRY_DISPATCHED",
                })
                pre_update = atomic_reconcile_cps(root / "docs/programs/V7_CURRENT_PROGRAM_STATE.md", state=active_state)
                if not pre_update.get("ok"):
                    result = {
                        "schema": "v7-omp-external-reentry/v1", "reentry_outcome": "REENTRY_FAILED_SAFE",
                        "final_verdict": "STOP_SAFE", "errors": pre_update.get("errors") or ["atomic_pre_trigger_state_failed"],
                        "standard_entrypoint_invoked": False, "consumer_invoked": False,
                    }
                else:
                    runner = continue_runner or _external_reentry_run_standard_entrypoint
                    continue_result = runner(root)
                    continue_ok = (
                        continue_result.get("final_verdict") in {"PASS", "BOUNDED_CONTINUATION"}
                        and int(continue_result.get("subprocess_returncode", 0)) == 0
                    )
                    completed_at = datetime.now(timezone.utc)
                    requested_timestamp = _plain_live_value(fresh_live, "WAKE_REQUESTED_AT")
                    try:
                        requested_time = _parse_iso_timestamp(requested_timestamp)
                        wake_latency_ms = max(0, int((actual_now - requested_time).total_seconds() * 1000))
                    except (TypeError, ValueError):
                        wake_latency_ms = 0
                    fallback_count = int(_plain_live_value(fresh_live, "WATCHDOG_FALLBACK_COUNT") or "0")
                    if watchdog_recovery:
                        fallback_count += 1
                    immediate_count = int(_plain_live_value(fresh_live, "IMMEDIATE_INVOCATION_COUNT") or "0")
                    if not watchdog_recovery and continue_ok:
                        immediate_count += 1
                    completed_generation = f"cpsgen_V7_REENTRY_COMPLETE_{event_identity[:12].upper()}"
                    evidence_fingerprint = hashlib.sha256(
                        json.dumps(continue_result, ensure_ascii=False, sort_keys=True, default=str).encode("utf-8")
                    ).hexdigest()
                    latest_cps_text = (
                        root / "docs/programs/V7_CURRENT_PROGRAM_STATE.md"
                    ).read_text(encoding="utf-8")
                    latest_live = _markdown_field_table(_markdown_section(
                        latest_cps_text,
                        "## 0. Authoritative Live Current State",
                        "## Authoritative Unfinished Capability Closure Registry",
                    ))
                    # An active Service-Failure incident is continued by the
                    # production-owned Matrix timer.  Once the external
                    # bridge has mirrored its verified outcome into source
                    # CPS and the existing OMP loop has acknowledged that
                    # Matrix consumer, scheduling another Codex wake adds no
                    # consumer and creates a self-sustaining observer loop.
                    # Keep external re-entry for engineering frontiers, but
                    # let this already-deployed runtime owner own the next
                    # fresh revalidation.
                    matrix_owned_incident_drain = (
                        continue_result.get("priority_decision")
                        == "ACTIVE_INCIDENT_DRAIN_PREEMPTS_GENERIC_POLYGON"
                        and continue_result.get("real_consumer")
                        == "tools/v7-service-matrix-refresh-all"
                    )
                    successor_required = all((
                        continue_ok,
                        _plain_live_value(latest_live, "OMP_CONTINUATION_REQUIRED") == "TRUE",
                        _plain_live_value(latest_live, "EXTERNAL_INPUT_REQUIRED") == "FALSE",
                        _plain_live_value(latest_live, "NEXT_MISSION_FORMED") == "TRUE",
                        _plain_live_value(latest_live, "NEXT_MISSION_ID") not in {"", "NONE"},
                    )) and not matrix_owned_incident_drain
                    successor_projection = dict(latest_live)
                    successor_projection["CURRENT_STATE_GENERATION"] = completed_generation
                    successor_projection["CURRENT_TRANSITION_ID"] = "EXTERNAL_REENTRY_COMPLETED_V1"
                    successor_event_id = (
                        event_driven_wake_identity(successor_projection)
                        if successor_required else "NONE"
                    )
                    final_state = normalized_cps_live_state({
                        **_normalized_state_from_live_cps(latest_cps_text),
                        "state_captured": completed_at.isoformat(),
                        "current_state_generation": completed_generation,
                        "current_transition_id": "EXTERNAL_REENTRY_COMPLETED_V1" if continue_ok else "EXTERNAL_REENTRY_FAILED_SAFE_V1",
                        "heartbeat_status": "ACTIVE", "automation_enabled": "TRUE",
                        "heartbeat_automation_level": "EXTERNAL_STANDARD_CONTINUE_OMP_REENTRY_ACTIVE",
                        "heartbeat_last_wakeup_id": wakeup_run_id, "heartbeat_last_event_id": event_identity,
                        "heartbeat_last_cps_generation": completed_generation,
                        "heartbeat_last_dependency_fingerprint": current_dependency,
                        "heartbeat_last_decision": "REENTRY_COMPLETED" if continue_ok else "REENTRY_FAILED_SAFE",
                        "heartbeat_last_run_at": completed_at.isoformat(),
                        "background_automation_state": reentry_background_state,
                        "external_reentry_enabled": "TRUE", "reentry_active_lease": "NONE",
                        "reentry_last_completed_id": invocation_id if continue_ok else "NONE",
                        "reentry_last_trigger_id": event_identity, "reentry_last_trigger_at": actual_now.isoformat(),
                        "reentry_last_invocation_id": invocation_id,
                        "reentry_platform_health": "PASS" if continue_ok else "FAILED_SAFE",
                        "no_progress_fingerprint": evidence_fingerprint,
                        "external_reentry_mode": EVENT_DRIVEN_REENTRY_MODE,
                        "event_driven_external_reentry_status": _plain_live_value(fresh_live, "EVENT_DRIVEN_EXTERNAL_REENTRY_STATUS"),
                        "heartbeat_role": "WATCHDOG_FALLBACK",
                        "immediate_wake_owner": EVENT_DRIVEN_WAKE_OWNER,
                        "last_wake_request_id": successor_event_id if successor_required else _plain_live_value(fresh_live, "LAST_WAKE_REQUEST_ID"),
                        "last_dispatched_wake_id": event_identity if event_identity_override else _plain_live_value(fresh_live, "LAST_DISPATCHED_WAKE_ID"),
                        "last_consumed_wake_id": event_identity if continue_ok else _plain_live_value(fresh_live, "LAST_CONSUMED_WAKE_ID"),
                        "pending_wake_id": successor_event_id if successor_required else "NONE" if continue_ok else event_identity,
                        "wake_source_cps_generation": completed_generation if successor_required else _plain_live_value(fresh_live, "WAKE_SOURCE_CPS_GENERATION"),
                        "wake_transition_id": "EXTERNAL_REENTRY_COMPLETED_V1" if successor_required else _plain_live_value(fresh_live, "WAKE_TRANSITION_ID"),
                        "wake_requested_at": completed_at.isoformat() if successor_required else requested_timestamp or actual_now.isoformat(),
                        "wake_dispatched_at": (
                            "NONE" if successor_required else
                            actual_now.isoformat()
                            if watchdog_recovery else
                            _plain_live_value(fresh_live, "WAKE_DISPATCHED_AT")
                            if _plain_live_value(fresh_live, "WAKE_DISPATCHED_AT") not in {"", "NONE"}
                            else actual_now.isoformat()
                        ),
                        "wake_started_at": "NONE" if successor_required else actual_now.isoformat(),
                        "wake_completed_at": "NONE" if successor_required else completed_at.isoformat(),
                        "measured_wake_latency_ms": str(wake_latency_ms),
                        "writer_blocking_time_ms": _plain_live_value(fresh_live, "WRITER_BLOCKING_TIME_MS"),
                        "watchdog_state": "ARMED_PENDING_IMMEDIATE_DISPATCH" if successor_required else "ARMED_FALLBACK_ONLY" if continue_ok else "PENDING_WATCHDOG_RECOVERY",
                        "watchdog_fallback_count": str(fallback_count),
                        "watchdog_recovery_result": "PASS" if watchdog_recovery and continue_ok else _plain_live_value(fresh_live, "WATCHDOG_RECOVERY_RESULT"),
                        "immediate_invocation_count": str(immediate_count),
                        "immediate_duplicate_suppression_count": _plain_live_value(fresh_live, "IMMEDIATE_DUPLICATE_SUPPRESSION_COUNT") or "0",
                        "overlap_count": _plain_live_value(fresh_live, "OVERLAP_COUNT") or "0",
                        "immediate_last_legal_terminal": "IMMEDIATE_REENTRY_REQUESTED" if successor_required else "IMMEDIATE_REENTRY_COMPLETED" if continue_ok else "IMMEDIATE_REENTRY_FAILED_SAFE",
                    })
                    matrix_successor_overrides = (
                        {
                            "CURRENT_SERVICE_FAILURE_NEXT_REQUIRED_CONSUMER": "`tools/v7-service-matrix-refresh-all`",
                            "CURRENT_SERVICE_FAILURE_REENTRY_CONDITION": "`enabled v7-service-matrix-refresh.timer performs fresh observation and consumes the durable active-incident successor`",
                        }
                        if matrix_owned_incident_drain else None
                    )
                    post_update = atomic_reconcile_cps(
                        root / "docs/programs/V7_CURRENT_PROGRAM_STATE.md",
                        state=final_state,
                        request_external_wake=False,
                        section0_field_overrides=matrix_successor_overrides,
                    )
                    post_ok = post_update.get("ok") is True and post_update.get("post_write_reread") == "PASS"
                    transition_count = len(continue_result.get("transitions") or ())
                    consumer_invoked = bool(continue_result.get("real_consumer")) or transition_count > 0
                    result = {
                        "schema": "v7-omp-external-reentry/v1", "event_id": event_identity,
                        "wakeup_run_id": wakeup_run_id, "platform_owner": "CODEX_AUTOMATION_PLATFORM",
                        "scheduled_event_time": normalized_time, "actual_execution_time": actual_now.isoformat(),
                        "invocation_id": invocation_id, "lease_id": lease_id,
                        "lease_acquisition_outcome": lease_result["outcome"],
                        "stale_lease_recovered": lease_result.get("stale_recovered") is True,
                        "cps_generation_before": current_generation, "cps_generation_active": active_generation,
                        "cps_generation_after": completed_generation if post_ok else "POST_WRITE_FAILED",
                        "standard_entrypoint": EXTERNAL_REENTRY_STANDARD_ENTRYPOINT,
                        "standard_entrypoint_invoked": True,
                        "real_caller": "continue_omp_engineering_control_loop",
                        "real_consumer": continue_result.get("real_consumer", "OMP_PROGRAM_EXECUTION_RECONCILIATION"),
                        "consumer_invoked": consumer_invoked, "internal_iteration_count": transition_count,
                        "behavior_change": transition_count > 0 and post_ok,
                        "next_output": continue_result.get("exact_next_operator_command") or continue_result.get("program_terminal"),
                        "bounded_terminal": continue_result.get("program_terminal"),
                        "trigger_mode": event_source_kind,
                        "wake_requested_at": requested_timestamp,
                        "wake_started_at": actual_now.isoformat(),
                        "wake_completed_at": completed_at.isoformat(),
                        "measured_wake_latency_ms": wake_latency_ms,
                        "watchdog_recovery": watchdog_recovery,
                        "continue_omp_result": continue_result, "atomic_pre_trigger_state": pre_update,
                        "atomic_post_trigger_state": post_update,
                        "matrix_owned_incident_drain": matrix_owned_incident_drain,
                        "reentry_outcome": "REENTRY_COMPLETED" if continue_ok and post_ok else "REENTRY_FAILED_SAFE",
                        "no_overlap": True, "duplicate_suppression": True, "no_user_prompt": True,
                        "runtime_impact": "NONE", "production_impact": "NONE", "authority_impact": "NONE",
                        "final_verdict": "PASS" if continue_ok and post_ok and consumer_invoked else "STOP_SAFE",
                        "errors": [] if continue_ok and post_ok and consumer_invoked else sorted(set(
                            (continue_result.get("errors") or []) + (post_update.get("errors") or [])
                        )),
                    }
        finally:
            try:
                current_lease = json.loads(resolved_lease_path.read_text(encoding="utf-8"))
            except (OSError, json.JSONDecodeError):
                current_lease = {}
            if current_lease.get("lease_id") == lease_id:
                with contextlib.suppress(OSError):
                    resolved_lease_path.unlink()
                lease_released = not resolved_lease_path.exists()
        result["lease_released"] = lease_released
        result["terminal_release"] = "PASS" if lease_released else "FAIL"
        if not lease_released:
            result["reentry_outcome"] = "REENTRY_FAILED_SAFE"
            result["final_verdict"] = "STOP_SAFE"
            result.setdefault("errors", []).append("terminal_lease_release_failed")
        journal = evidence_path if evidence_path is not None else _external_reentry_evidence_path(root)
        if journal:
            _append_external_reentry_evidence(journal, result)
        return result

    reconciliation = program_execution_reconciliation(sources)
    reconciliation_payload = json.dumps(
        reconciliation, ensure_ascii=False, sort_keys=True, separators=(",", ":")
    )
    decision_payload = {
        "schema": "v7.omp-heartbeat-consumer-decision.v1",
        "event_id": event_identity,
        "wakeup_run_id": wakeup_run_id,
        "cps_generation": current_generation,
        "adapter_result": activation,
        "reconciliation_fingerprint": hashlib.sha256(reconciliation_payload.encode("utf-8")).hexdigest(),
        "program_frontier": reconciliation.get("executable_program_frontier") or [],
    }
    decision_fingerprint = hashlib.sha256(
        json.dumps(decision_payload, sort_keys=True, separators=(",", ":")).encode("utf-8")
    ).hexdigest()
    reconciliation_ok = reconciliation.get("final_verdict") == "PASS"
    legal_no_action = activation in {
        "NO_CHANGE_DEPENDENCY_UNCHANGED",
        "NO_CHANGE_NO_WAITING_CAPABILITY",
        "NO_CHANGE_EVIDENCE_INSUFFICIENT",
    }
    ready = activation == "READY_FRONTIER_AVAILABLE_DRY_RUN_ONLY"
    consumer_decision = (
        "LEGAL_NO_ACTION" if reconciliation_ok and legal_no_action
        else "READY_FRONTIER_AVAILABLE" if reconciliation_ok and ready
        else "STOP_SAFE_RECONCILIATION_FAILURE"
    )
    next_output = (
        "WAIT_FOR_OWNER_BACKED_DEPENDENCY_CHANGE" if consumer_decision == "LEGAL_NO_ACTION"
        else (reconciliation.get("executable_program_frontier") or ["NONE"])[0]
        if consumer_decision == "READY_FRONTIER_AVAILABLE"
        else "STOP_SAFE"
    )
    errors = sorted(set(adapter.get("errors") or ()) | set(reconciliation.get("errors") or ()))
    return {
        "schema": "v7-omp-heartbeat-program-reentry/v1",
        "event_id": event_identity,
        "wakeup_run_id": wakeup_run_id,
        "fresh_cps_generation": current_generation,
        "dependency_fingerprint": current_dependency,
        "adapter": adapter,
        "reconciliation_invoked": True,
        "reconciliation": reconciliation,
        "decision_trace_id": f"omphb_{decision_fingerprint[:24]}",
        "decision_fingerprint": decision_fingerprint,
        "consumer": "OMP_HEARTBEAT_REENTRY_CONSUMER",
        "consumer_invoked": True,
        "consumer_decision": consumer_decision,
        "consumer_behavior_change_or_legal_no_action": consumer_decision in {"LEGAL_NO_ACTION", "READY_FRONTIER_AVAILABLE"},
        "next_output": next_output,
        "legal_terminal": consumer_decision == "LEGAL_NO_ACTION",
        "next_trigger_policy": "NATURAL_SCHEDULE_ONLY_NO_RECURSION",
        "idempotency_key": f"{event_identity}:{wakeup_run_id}:{current_generation}:{current_dependency}",
        "no_unbounded_recursion": True,
        "mission_created": False,
        "candidate_created": False,
        "packet_created": False,
        "cps_mutated": False,
        "git_changed": False,
        "runtime_impact": "NONE",
        "production_impact": "NONE",
        "authority_impact": "NONE",
        "final_verdict": "PASS" if consumer_decision != "STOP_SAFE_RECONCILIATION_FAILURE" else "STOP_SAFE",
        "errors": errors,
    }


BDP_CANDIDATE_REQUIRED_FIELDS = (
    "primary_class",
    "secondary_classes",
    "execution_depth",
    "engineering_intent",
    "current_reality",
    "expected_reality",
    "engineering_chain",
    "engineering_chain_segment",
    "behaviour_instance",
    "behaviour",
    "automation_logic",
    "automation_break",
    "existing_rule",
    "current_outcome",
    "expected_outcome",
    "intent_closure_state",
    "owner",
    "producer",
    "consumer",
    "evidence",
    "implementation_scope",
    "runtime_impact",
    "production_impact",
    "dependencies",
    "verification",
    "verification_context",
    "rollback",
    "authority",
    "authority_context",
    "terminal_path",
    "implementation_readiness",
    "omp_consumer",
    "codex_readiness",
)


def _bdp_normalized_value(value: Any) -> Any:
    if isinstance(value, str):
        return " ".join(value.split()).casefold()
    if isinstance(value, (list, tuple, set)):
        return sorted(_bdp_normalized_value(item) for item in value)
    if isinstance(value, dict):
        return {
            str(key): _bdp_normalized_value(value[key])
            for key in sorted(value)
        }
    return value


def _bdp_candidate_meaning(gap: dict[str, Any]) -> dict[str, Any]:
    identity_fields = (
        "primary_class",
        "execution_depth",
        "engineering_intent",
        "current_reality",
        "expected_reality",
        "engineering_chain",
        "engineering_chain_segment",
        "behaviour_instance",
        "automation_break",
        "owner",
        "consumer",
        "implementation_scope",
    )
    return {
        "identity_schema": "v7.bdp-candidate-meaning.v1",
        **{
            field: _bdp_normalized_value(gap[field])
            for field in identity_fields
        },
    }


def omp_candidate_admission_decision(
    candidate: dict[str, Any],
    *,
    mission_id: str = "",
    existing_candidate_ids: Optional[Iterable[str]] = None,
) -> dict[str, Any]:
    """Consume one BDP Candidate through the existing bounded OMP admission gates."""
    missing = [
        field
        for field in ("candidate_instance_id", "identity_sha256", *BDP_CANDIDATE_REQUIRED_FIELDS)
        if field not in candidate or candidate[field] is None or candidate[field] == ""
    ]
    errors: list[str] = []
    if missing:
        errors.extend(f"candidate_field_missing:{field}" for field in missing)

    identity = str(candidate.get("identity_sha256") or "")
    candidate_id = str(candidate.get("candidate_instance_id") or "")
    if not re.fullmatch(r"[0-9a-f]{64}", identity):
        errors.append("candidate_identity_hash_invalid")
    if candidate_id != f"BDP-ICI-{identity[:24].upper()}":
        errors.append("candidate_identity_id_mismatch")
    duplicate = candidate_id in {str(item) for item in existing_candidate_ids or ()}
    if duplicate:
        errors.append("candidate_identity_duplicate")

    if candidate.get("implementation_readiness") != "IMPLEMENTATION_READY":
        errors.append("candidate_implementation_not_ready")
    if candidate.get("runtime_impact") != "NONE":
        errors.append("candidate_runtime_boundary_not_none")
    if candidate.get("production_impact") != "NONE":
        errors.append("candidate_production_boundary_not_none")
    if candidate.get("dependencies") not in {"NONE", "COMPLETED", "EXISTING_CONTRACTS_READY"}:
        errors.append("candidate_dependency_not_ready")
    if candidate.get("intent_closure_state") != "AUTOMATION_BREAK":
        errors.append("candidate_intent_closure_state_invalid")
    if candidate.get("omp_consumer") != "OMP_CANDIDATE_ADMISSION":
        errors.append("candidate_omp_consumer_invalid")
    for field in (
        "new_owner_required",
        "new_backlog_required",
        "new_runtime_required",
        "new_architecture_required",
        "authority_expansion_required",
    ):
        if candidate.get(field) is not False:
            errors.append(f"candidate_boundary_invalid:{field}")

    unique = sorted(set(errors))
    accepted = not unique
    resolved_mission_id = mission_id or f"V7_OMP_BDP_{identity[:24].upper()}_V1"
    decision_payload = {
        "schema": "v7.omp-candidate-admission-trace.v1",
        "candidate_instance_id": candidate_id,
        "candidate_identity": identity,
        "mission_id": resolved_mission_id if accepted else "NONE",
        "decision": "MISSION_ACCEPTED" if accepted else "MISSION_NOT_APPLICABLE" if duplicate else "MISSION_REJECTED",
        "errors": unique,
    }
    decision_fingerprint = hashlib.sha256(
        json.dumps(decision_payload, sort_keys=True, separators=(",", ":")).encode("utf-8")
    ).hexdigest()
    return {
        "schema": "v7-omp-candidate-admission-decision/v1",
        "identity_result": "IDENTITY_VALID" if not any("identity" in item for item in unique) else "IDENTITY_INVALID",
        "eligibility_result": "ELIGIBLE" if accepted else "REJECT",
        "duplicate_check_result": "DUPLICATE" if duplicate else "UNIQUE",
        "admission_decision": "MISSION_ACCEPTED" if accepted else "MISSION_NOT_APPLICABLE" if duplicate else "MISSION_REJECTED",
        "mission_created": accepted,
        "mission_state": "PREPARED_NOT_ACTIVE" if accepted else "NONE",
        "mission_id": resolved_mission_id if accepted else "NONE",
        "decision_trace_id": f"ompdt_{decision_fingerprint[:24]}",
        "decision_fingerprint": decision_fingerprint,
        "mission_executed": False,
        "runtime_impact": "NONE",
        "production_impact": "NONE",
        "authority_expansion": False,
        "final_verdict": "PASS" if accepted else "STOP_SAFE",
        "errors": unique,
    }


def bdp_development_impulse_handoff(
    engineering_state: dict[str, Any],
    *,
    existing_candidates: Optional[Iterable[Any]] = None,
) -> dict[str, Any]:
    """Route one bounded owner-backed BDP gap to OMP, or return legal no-action."""
    errors: list[str] = []
    generation = str(engineering_state.get("state_generation") or "")
    decision = str(engineering_state.get("discovery_economy_decision") or "")
    gaps = engineering_state.get("engineering_gaps")
    try:
        real_world_limit_intents = int(engineering_state.get("real_world_limit_intents") or 0)
        if real_world_limit_intents < 0:
            raise ValueError
    except (TypeError, ValueError):
        real_world_limit_intents = 0
        errors.append("bdp_real_world_limit_intents_invalid")
    if not re.fullmatch(r"[A-Za-z0-9_.:-]{8,160}", generation):
        errors.append("bdp_state_generation_invalid")
    if decision != "DISCOVERY_NOT_REQUIRED_REUSE_EVIDENCE":
        errors.append("bdp_discovery_economy_not_ready_for_reuse")
    if not isinstance(gaps, list):
        errors.append("bdp_engineering_gaps_invalid")

    if errors:
        return {
            "schema": "v7-omp-bdp-development-impulse-handoff/v1",
            "handoff_status": "STOP_SAFE",
            "candidate_production_status": "NO_CANDIDATE",
            "candidate_count": 0,
            "candidate": None,
            "admission_decision": "NONE",
            "mission_created": False,
            "mission_executed": False,
            "runtime_impact": "NONE",
            "production_impact": "NONE",
            "authority_expansion": False,
            "final_verdict": "STOP_SAFE",
            "errors": sorted(set(errors)),
        }

    if not gaps:
        return {
            "schema": "v7-omp-bdp-development-impulse-handoff/v1",
            "handoff_status": "NO_ACTION_REQUIRED",
            "candidate_production_status": "NO_ACTION",
            "candidate_count": 0,
            "candidate": None,
            "admission_decision": "MISSION_NOT_APPLICABLE",
            "terminal_consumer": "OMP_NEXT_ACTION",
            "mission_created": False,
            "mission_executed": False,
            "runtime_impact": "NONE",
            "production_impact": "NONE",
            "authority_expansion": False,
            "real_world_limit_intents_preserved": real_world_limit_intents,
            "final_verdict": "PASS",
            "errors": [],
        }

    if len(gaps) != 1 or not isinstance(gaps[0], dict):
        return {
            "schema": "v7-omp-bdp-development-impulse-handoff/v1",
            "handoff_status": "STOP_SAFE",
            "candidate_production_status": "AMBIGUOUS_BOUNDED_SCOPE",
            "candidate_count": 0,
            "candidate": None,
            "admission_decision": "NONE",
            "mission_created": False,
            "mission_executed": False,
            "runtime_impact": "NONE",
            "production_impact": "NONE",
            "authority_expansion": False,
            "final_verdict": "STOP_SAFE",
            "errors": ["bdp_bounded_scope_requires_exactly_one_gap"],
        }

    gap = gaps[0]
    missing = [
        field
        for field in BDP_CANDIDATE_REQUIRED_FIELDS
        if field not in gap or gap[field] is None or gap[field] == ""
    ]
    for field in missing:
        errors.append(f"bdp_gap_field_missing:{field}")
    if gap.get("new_owner_required") is not False:
        errors.append("bdp_gap_requires_new_owner")
    if gap.get("new_architecture_required") is not False:
        errors.append("bdp_gap_requires_new_architecture")
    if errors:
        return {
            "schema": "v7-omp-bdp-development-impulse-handoff/v1",
            "handoff_status": "STOP_SAFE",
            "candidate_production_status": "INVALID_GAP",
            "candidate_count": 0,
            "candidate": None,
            "admission_decision": "NONE",
            "mission_created": False,
            "mission_executed": False,
            "runtime_impact": "NONE",
            "production_impact": "NONE",
            "authority_expansion": False,
            "final_verdict": "STOP_SAFE",
            "errors": sorted(set(errors)),
        }

    meaning = _bdp_candidate_meaning(gap)
    encoded = json.dumps(meaning, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode("utf-8")
    identity = hashlib.sha256(encoded).hexdigest()
    candidate_id = f"BDP-ICI-{identity[:24].upper()}"
    candidate = {
        "candidate_instance_id": candidate_id,
        "identity_sha256": identity,
        "meaning_fingerprint": identity,
        "identity_schema": meaning["identity_schema"],
        "state_generation": generation,
        **gap,
        "new_owner_required": False,
        "new_backlog_required": False,
        "new_runtime_required": False,
        "new_architecture_required": False,
        "authority_expansion_required": False,
    }

    existing_ids: set[str] = set()
    existing_meanings: set[str] = set()
    for item in existing_candidates or ():
        if isinstance(item, str):
            existing_ids.add(item)
        elif isinstance(item, dict):
            existing_ids.add(str(item.get("candidate_instance_id") or ""))
            existing_meanings.add(str(item.get("meaning_fingerprint") or ""))
    if candidate_id in existing_ids or identity in existing_meanings:
        return {
            "schema": "v7-omp-bdp-development-impulse-handoff/v1",
            "handoff_status": "DUPLICATE_SUPPRESSED",
            "candidate_production_status": "DUPLICATE_EXISTING_CANDIDATE",
            "candidate_count": 0,
            "candidate": None,
            "existing_candidate_id": candidate_id,
            "admission_decision": "MISSION_NOT_APPLICABLE",
            "terminal_consumer": "EXISTING_CANDIDATE_LIFECYCLE",
            "mission_created": False,
            "mission_executed": False,
            "runtime_impact": "NONE",
            "production_impact": "NONE",
            "authority_expansion": False,
            "final_verdict": "PASS",
            "errors": [],
        }

    admission = omp_candidate_admission_decision(candidate)
    return {
        "schema": "v7-omp-bdp-development-impulse-handoff/v1",
        "handoff_status": "CANDIDATE_CONSUMED_BY_OMP" if admission["final_verdict"] == "PASS" else "STOP_SAFE",
        "candidate_production_status": "ONE_DETERMINISTIC_CANDIDATE",
        "candidate_count": 1,
        "candidate": candidate,
        "admission": admission,
        "admission_decision": admission["admission_decision"],
        "mission_created": admission["mission_created"],
        "mission_executed": False,
        "runtime_impact": "NONE",
        "production_impact": "NONE",
        "authority_expansion": False,
        "final_verdict": admission["final_verdict"],
        "errors": admission["errors"],
    }


def bdp_development_impulse_from_cps(
    cps_text: str,
    *,
    engineering_gaps: Optional[list[dict[str, Any]]] = None,
    existing_candidates: Optional[Iterable[Any]] = None,
) -> dict[str, Any]:
    """Evaluate the BDP handoff from fresh CPS without mutating the CPS owner."""
    live = _markdown_field_table(_markdown_section(
        cps_text,
        "## 0. Authoritative Live Current State",
        "## Authoritative Unfinished Capability Closure Registry",
    ))
    registry = _markdown_field_table(_markdown_section(
        cps_text,
        "### Registry Metadata And Truth Lifecycle",
        "### Active Protected Work In Progress",
    ))
    dependency = capability_dependency_consistency(cps_text)
    if dependency["final_verdict"] != "PASS":
        return {
            "schema": "v7-omp-bdp-development-impulse-handoff/v1",
            "handoff_status": "STOP_SAFE",
            "candidate_production_status": "INVALID_CPS_DEPENDENCY_STATE",
            "candidate_count": 0,
            "candidate": None,
            "admission_decision": "NONE",
            "mission_created": False,
            "mission_executed": False,
            "runtime_impact": "NONE",
            "production_impact": "NONE",
            "authority_expansion": False,
            "final_verdict": "STOP_SAFE",
            "errors": list(dependency["errors"]),
        }
    open_intents = registry.get("OPEN_ENGINEERING_INTENTS", "0").strip("`")
    try:
        real_world_limit_intents = int(open_intents)
    except ValueError:
        real_world_limit_intents = 0
    return bdp_development_impulse_handoff(
        {
            "state_generation": live.get("CURRENT_STATE_GENERATION", "").strip("`"),
            "discovery_economy_decision": "DISCOVERY_NOT_REQUIRED_REUSE_EVIDENCE",
            "engineering_gaps": list(engineering_gaps or ()),
            "real_world_limit_intents": real_world_limit_intents,
        },
        existing_candidates=existing_candidates,
    )


POLYGON_SCENARIO_SOURCE_REQUIRED_FIELDS = (
    "source_owner",
    "source_evidence",
    "engineering_intent",
    "current_reality",
    "expected_reality",
    "target_rule_or_contract",
    "failure_or_gap_class",
    "affected_producer",
    "affected_consumer",
    "boundary",
    "stimulus_or_replay_input",
    "expected_observation",
    "pass_criteria",
    "fail_criteria",
    "implementation_allowed",
    "verification_plan",
    "rollback_or_stop_safe",
    "runtime_impact",
    "production_impact",
    "authority_impact",
    "maturity_impact",
)

POLYGON_SCENARIO_PRIORITY = {
    "CURRENT_TRUTH_CONTRADICTION": 10,
    "STOP_SAFE_OR_ROLLBACK_GAP": 20,
    "PRODUCER_CONSUMER_CHAIN_GAP": 30,
    "DETERMINISTIC_REPLAY_OR_DUPLICATE_GAP": 40,
    "DEPENDENCY_OR_AUTHORITY_BOUNDARY_GAP": 50,
    "CANONICAL_RULE_VERIFICATION_GAP": 60,
    "HISTORICAL_DEFECT_REGRESSION_GAP": 70,
    "EXECUTION_CERTIFICATION_COVERAGE_GAP": 80,
    "ENGINEERING_QUALITY_GAP": 90,
}


def _polygon_scenario_meaning(source: dict[str, Any]) -> dict[str, Any]:
    fields = (
        "source_owner",
        "engineering_intent",
        "current_reality",
        "expected_reality",
        "target_rule_or_contract",
        "failure_or_gap_class",
        "affected_producer",
        "affected_consumer",
        "boundary",
        "stimulus_or_replay_input",
        "expected_observation",
    )
    return {
        "identity_schema": "v7.engineering-polygon-scenario-meaning.v1",
        **{field: _bdp_normalized_value(source[field]) for field in fields},
    }


def engineering_polygon_scenario_instance(source: dict[str, Any]) -> dict[str, Any]:
    """Materialize one bounded owner-backed scenario without creating a new lifecycle."""
    errors = [
        f"scenario_source_field_missing:{field}"
        for field in POLYGON_SCENARIO_SOURCE_REQUIRED_FIELDS
        if field not in source or source[field] is None or source[field] == ""
    ]
    gap_class = str(source.get("failure_or_gap_class") or "")
    if gap_class not in POLYGON_SCENARIO_PRIORITY:
        errors.append("scenario_gap_class_unknown")
    if source.get("runtime_impact") != "NONE":
        errors.append("scenario_runtime_boundary")
    if source.get("production_impact") != "NONE":
        errors.append("scenario_production_boundary")
    if source.get("authority_impact") not in {"NONE", False}:
        errors.append("scenario_authority_boundary")
    if source.get("maturity_impact") != "PRODUCTION_MATURITY_CREDIT_FORBIDDEN":
        errors.append("scenario_maturity_boundary")
    if source.get("new_owner_required") is not False:
        errors.append("scenario_new_owner_boundary")
    if source.get("new_architecture_required") is not False:
        errors.append("scenario_new_architecture_boundary")
    if source.get("implementation_allowed") is not True:
        errors.append("scenario_implementation_not_allowed")
    unique = sorted(set(errors))
    if unique:
        return {
            "schema": "v7-engineering-polygon-scenario-instance/v1",
            "status": "STOP_SAFE",
            "scenario_instance": None,
            "final_verdict": "STOP_SAFE",
            "errors": unique,
        }
    meaning = _polygon_scenario_meaning(source)
    encoded = json.dumps(meaning, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode("utf-8")
    identity = hashlib.sha256(encoded).hexdigest()
    instance = {
        "schema": "v7-engineering-polygon-scenario-instance/v1",
        "scenario_instance_id": f"V7-POLYGON-SCENARIO-{identity[:24].upper()}",
        "deterministic_identity": identity,
        "duplicate_fingerprint": identity,
        "priority": POLYGON_SCENARIO_PRIORITY[gap_class],
        **source,
    }
    return {
        "schema": "v7-engineering-polygon-scenario-materialization/v1",
        "status": "SCENARIO_MATERIALIZED",
        "scenario_instance": instance,
        "final_verdict": "PASS",
        "errors": [],
    }


def reconcile_service_failure_execution_feedback_to_cps(
    feedback: dict[str, Any], *, root: Path = ROOT,
) -> dict[str, Any]:
    """Project one exact packet-bound service-failure outcome into source CPS.

    The production executor remains the only producer of the outcome.  This
    source-side consumer accepts no inferred correlation: the feedback must
    preserve the Matrix incident/event binding embedded in the Packet before
    it can update the volatile CPS description of the same incident.
    """
    binding = feedback.get("service_failure_causal_binding")
    binding = binding if isinstance(binding, dict) else {}
    execution = feedback.get("execution_outcome")
    execution = execution if isinstance(execution, dict) else {}
    verification = feedback.get("verification_result")
    verification = verification if isinstance(verification, dict) else {}
    source_incident_id = str(binding.get("source_incident_id") or "")
    source_event_id = str(binding.get("source_event_id") or "")
    source_channel = str(binding.get("source_channel") or "")
    feedback_id = str(feedback.get("feedback_id") or feedback.get("object_id") or "")
    packet_id = str(feedback.get("packet_id") or "")
    errors: list[str] = []
    if str(feedback.get("schema_version") or "") != "v7.execution-outcome-record.v1":
        errors.append("execution_feedback_schema_invalid")
    if not all((source_incident_id, source_event_id, source_channel, feedback_id, packet_id)):
        errors.append("execution_feedback_causal_binding_identity_missing")
    if str(binding.get("event_type") or "") not in {"SERVICE_FAILURE_OBSERVED", "SERVICE_FAILURE_REVALIDATED"}:
        errors.append("execution_feedback_causal_binding_event_type_invalid")
    if str(feedback.get("source_channel") or "") != source_channel:
        errors.append("execution_feedback_causal_binding_source_mismatch")
    terminal = str(feedback.get("terminal_outcome_classification") or "")
    success = terminal == "SUCCESS" and verification.get("success") is True
    rollback_success = terminal == "ROLLBACK_SUCCESS"
    if not (success or rollback_success):
        errors.append("execution_feedback_terminal_not_consumable")
    if execution.get("runtime_mutation_performed") is not True or int(execution.get("users_moved") or 0) != 1:
        errors.append("execution_feedback_exact_one_user_apply_not_proven")
    # Validate the immutable feedback identity before looking at its compact
    # scope projection.  A feedback id that CPS has already consumed is a
    # no-op: the live L3 scope may legitimately have advanced since that
    # outcome, so comparing an old Packet binding to the *new* scope would
    # turn an idempotent replay into a false STOP_SAFE.
    if errors:
        return {
            "schema_version": "v7.service-failure-execution-feedback-source-cps-reconciliation.v1",
            "final_verdict": "STOP_SAFE", "errors": sorted(set(errors)),
        }
    cps_path = root / "docs/programs/V7_CURRENT_PROGRAM_STATE.md"
    try:
        cps_text = cps_path.read_text(encoding="utf-8")
    except OSError as exc:
        return {
            "schema_version": "v7.service-failure-execution-feedback-source-cps-reconciliation.v1",
            "final_verdict": "STOP_SAFE", "errors": [f"cps_unreadable:{exc}"],
        }
    live = _markdown_field_table(_markdown_section(
        cps_text, "## 0. Authoritative Live Current State", "## Authoritative Unfinished Capability Closure Registry",
    ))
    if _plain_live_value(live, "ACTIVE_PROGRAM") != SERVICE_FAILURE_AUTOMATION_PROGRAM_ID:
        return {
            "schema_version": "v7.service-failure-execution-feedback-source-cps-reconciliation.v1",
            "final_verdict": "STOP_SAFE", "errors": ["service_failure_program_not_active_in_cps"],
        }
    if _plain_live_value(live, "LAST_SERVICE_FAILURE_EXECUTION_FEEDBACK_ID") == feedback_id:
        return {
            "schema_version": "v7.service-failure-execution-feedback-source-cps-reconciliation.v1",
            "final_verdict": "PASS", "status": "EXECUTION_FEEDBACK_ALREADY_CONSUMED",
            "feedback_id": feedback_id, "behavior_change": False, "errors": [],
        }

    scope_accounting = feedback.get("incident_scope_accounting")
    scope_accounting = scope_accounting if isinstance(scope_accounting, dict) else {}
    scope_available = bool(scope_accounting)
    if scope_available:
        affected_scope_count = int(scope_accounting.get("affected_scope_count") or 0)
        protected_scope_count = int(scope_accounting.get("protected_scope_count") or 0)
        unresolved_scope_count = int(scope_accounting.get("unresolved_scope_count") or 0)
        excluded_scope_count = int(scope_accounting.get("explicitly_excluded_or_recovered_scope_count") or 0)
        if str(scope_accounting.get("status") or "") != "ACCOUNTED":
            errors.append("execution_feedback_scope_accounting_not_accounted")
        if not str(scope_accounting.get("affected_scope_fingerprint") or ""):
            errors.append("execution_feedback_scope_fingerprint_missing")
        if bool(scope_accounting.get("raw_user_list_stored")):
            errors.append("execution_feedback_scope_raw_user_storage_forbidden")
        if affected_scope_count != protected_scope_count + unresolved_scope_count + excluded_scope_count:
            errors.append("execution_feedback_scope_accounting_unbalanced")
        binding_scope = binding.get("source_scope")
        binding_scope = binding_scope if isinstance(binding_scope, dict) else {}
        if (
            int(binding_scope.get("affected_scope_count") or -1) != affected_scope_count
            or str(binding_scope.get("affected_scope_fingerprint") or "")
            != str(scope_accounting.get("affected_scope_fingerprint") or "")
            or str(binding_scope.get("source_channel") or "") != source_channel
        ):
            errors.append("execution_feedback_scope_binding_mismatch")
    if errors:
        return {
            "schema_version": "v7.service-failure-execution-feedback-source-cps-reconciliation.v1",
            "final_verdict": "STOP_SAFE", "errors": sorted(set(errors)),
        }
    fingerprint = hashlib.sha256(json.dumps({
        "feedback_id": feedback_id,
        "source_incident_id": source_incident_id,
        "source_event_id": source_event_id,
        "packet_id": packet_id,
        "terminal": terminal,
    }, sort_keys=True, separators=(",", ":")).encode("utf-8")).hexdigest()
    state = _normalized_state_from_live_cps(cps_text)
    state.update({
        "state_captured": utc_now(),
        "current_state_generation": f"cpsgen_SFA_EXEC_{fingerprint[:12].upper()}",
        "current_transition_id": "SERVICE_FAILURE_FRESH_EVENT_EXECUTION_FEEDBACK_CONSUMED_V1",
        "current_active_scope": (
            "SERVICE_FAILURE_AUTOMATION_ACTIVE_INCIDENT_DRAIN"
            if scope_available and unresolved_scope_count > 0
            else "SERVICE_FAILURE_AUTOMATION_PARTIALLY_PROTECTED_INCIDENT_ACTIVE"
        ),
        "current_safe_next_action": (
            "CONTINUE THE SAME UNRECOVERED INCIDENT THROUGH A FRESH MATRIX REVALIDATION; "
            "each next operation requires a new Candidate, Packet and lease under the existing standing policy"
            if scope_available and unresolved_scope_count > 0 else
            "PRESERVE THE EXACT EXECUTION FEEDBACK; REMAIN READY FOR A FRESH OWNER-BACKED "
            "MATCHING SERVICE FAILURE BEFORE ANY NEW CANDIDATE/PACKET/LEASE"
        ),
        "transaction_terminal_class": terminal,
        "verification_result": "PASS" if success else "ROLLBACK_SUCCESS",
        "rollback_result": "NOT_REQUIRED" if success else "ROLLBACK_COMPLETED",
        "learning_result": "EXISTING_EXECUTION_FEEDBACK_CONSUMED",
        "user_movement": "ONE_BOUNDED_USER_MOVED_IN_EXECUTION_FEEDBACK; no scope expansion",
        "source_summary": (
            "The existing Matrix -> delegated Packet -> execution-feedback chain consumed one exact "
            "service-failure revalidation outcome into CPS; remaining scope requires a fresh matching event "
            "and fresh Candidate/Packet/lease identities."
        ),
    })
    scope_text = (
        f"; scope affected={affected_scope_count}, protected={protected_scope_count}, "
        f"unresolved={unresolved_scope_count}, excluded_or_recovered={excluded_scope_count}; "
        f"fingerprint {scope_accounting.get('affected_scope_fingerprint') or ''}"
        if scope_available else ""
    )
    incident_text = (
        f"PARTIALLY_PROTECTED; source incident {source_incident_id}; fresh event {source_event_id}; "
        f"one bounded user {feedback.get('user') or ''} moved from {source_channel} to "
        f"{feedback.get('target_channel') or ''}; feedback {feedback_id}; packet {packet_id}; "
        "remaining channel scope stays open and may only reenter on a fresh matching event"
        f"{scope_text}"
    )
    atomic = atomic_reconcile_cps(
        cps_path,
        state=state,
        request_external_wake=False,
        expected_generation=_plain_live_value(live, "CURRENT_STATE_GENERATION"),
        section0_field_overrides={
            "CURRENT_VLESS_SERVICE_INCIDENT": f"`{incident_text}`",
            "CURRENT_VLESS_SERVICE_INCIDENT_TERMINAL": (
                "`PARTIAL_PROTECTION_EXECUTION_CONSUMED; no historical Event/Candidate/Packet/lease may be reused`"
            ),
            "LAST_SERVICE_FAILURE_EXECUTION_FEEDBACK_ID": f"`{feedback_id}`",
            "LAST_SERVICE_FAILURE_EXECUTION_SOURCE_INCIDENT": f"`{source_incident_id}`",
            "LAST_SERVICE_FAILURE_EXECUTION_SOURCE_EVENT": f"`{source_event_id}`",
            "LAST_SERVICE_FAILURE_EXECUTION_PACKET": f"`{packet_id}`",
            "LAST_SERVICE_FAILURE_EXECUTION_OUTCOME": f"`{terminal}`",
            "LAST_SERVICE_FAILURE_EXECUTION_CONSUMPTION": "`PACKET_BOUND_FRESH_EVENT_OUTCOME_CONSUMED`",
            "CURRENT_VLESS_AFFECTED_SCOPE": (
                f"`{affected_scope_count}`" if scope_available else "`UNKNOWN_NOT_PROJECTED`"
            ),
            "CURRENT_VLESS_PROTECTED_SCOPE": (
                f"`{protected_scope_count}`" if scope_available else "`UNKNOWN_NOT_PROJECTED`"
            ),
            "CURRENT_VLESS_UNRESOLVED_SCOPE": (
                f"`{unresolved_scope_count}`" if scope_available else "`UNKNOWN_NOT_PROJECTED`"
            ),
            "CURRENT_VLESS_SCOPE_ACCOUNTING": (
                "`ACCOUNTED; existing Matrix -> L3 -> CPS consumer; raw user list not stored`"
                if scope_available else "`LEGACY_FEEDBACK_WITHOUT_COMPACT_SCOPE`"
            ),
        },
    )
    return {
        "schema_version": "v7.service-failure-execution-feedback-source-cps-reconciliation.v1",
        "final_verdict": "PASS" if atomic.get("ok") else "STOP_SAFE",
        "status": "PACKET_BOUND_FRESH_EVENT_EXECUTION_FEEDBACK_CONSUMED" if atomic.get("ok") else "CPS_UPDATE_FAILED",
        "feedback_id": feedback_id,
        "source_incident_id": source_incident_id,
        "source_event_id": source_event_id,
        "packet_id": packet_id,
        "atomic_update": atomic,
        "behavior_change": bool(atomic.get("ok")),
        "forbidden_effects": {
            "runtime_apply": False, "routing_mutation": False, "user_movement": 0,
            "authority_expansion": False, "production_maturity_change": False,
        },
        "errors": [] if atomic.get("ok") else atomic.get("errors") or ["cps_execution_feedback_projection_failed"],
    }


def select_engineering_polygon_scenario(
    sources: Iterable[Any],
    *,
    existing_scenarios: Optional[Iterable[Any]] = None,
) -> dict[str, Any]:
    """Select exactly one deterministic engineering-plane scenario through existing OMP priority."""
    materialized: list[dict[str, Any]] = []
    excluded: list[dict[str, str]] = []
    invalid: list[str] = []
    for index, source in enumerate(sources):
        if not isinstance(source, dict):
            invalid.append(f"scenario_source_invalid:{index}")
            continue
        if (
            source.get("production_impact") not in {None, "NONE"}
            or source.get("runtime_impact") not in {None, "NONE"}
        ):
            excluded.append({"source": str(source.get("source_evidence") or index), "reason": "PRODUCTION_CONTOUR_ONLY"})
            continue
        result = engineering_polygon_scenario_instance(source)
        if result["final_verdict"] != "PASS":
            invalid.extend(result["errors"])
            continue
        materialized.append(result["scenario_instance"])

    if invalid:
        return {
            "schema": "v7-engineering-polygon-scenario-selection/v1",
            "selection_status": "STOP_SAFE",
            "selected_scenario": None,
            "evaluated_source_count": len(materialized) + len(excluded) + len(invalid),
            "valid_scenario_count": len(materialized),
            "excluded_sources": excluded,
            "final_verdict": "STOP_SAFE",
            "errors": sorted(set(invalid)),
        }

    existing_ids: set[str] = set()
    existing_meanings: set[str] = set()
    for item in existing_scenarios or ():
        if isinstance(item, str):
            existing_ids.add(item)
        elif isinstance(item, dict):
            existing_ids.add(str(item.get("scenario_instance_id") or ""))
            existing_meanings.add(str(item.get("duplicate_fingerprint") or ""))
    ordered = sorted(
        materialized,
        key=lambda row: (int(row["priority"]), str(row["deterministic_identity"])),
    )
    remaining = [
        row for row in ordered
        if row["scenario_instance_id"] not in existing_ids
        and row["duplicate_fingerprint"] not in existing_meanings
    ]
    duplicates = len(ordered) - len(remaining)
    selected = remaining[0] if remaining else None
    return {
        "schema": "v7-engineering-polygon-scenario-selection/v1",
        "selection_status": "SCENARIO_SELECTED" if selected else "NO_VALID_ENGINEERING_SCENARIO",
        "selected_scenario": selected,
        "evaluated_source_count": len(materialized) + len(excluded),
        "valid_scenario_count": len(materialized),
        "duplicate_scenario_count": duplicates,
        "remaining_distinct_scenario_count": len(remaining),
        "excluded_sources": excluded,
        "final_verdict": "PASS",
        "errors": [],
    }


